// Plus Two entrance chemistry bank: Chemical equilibrium (not ionic equilibrium). Original fibub questions.
// Data used: R = 0.0821 L atm K^-1 mol^-1 (Kp, Kc) and 8.314 J K^-1 mol^-1 (van't Hoff, dG = -RT ln K); 2.303 RT at 298 K = 5.71 kJ/mol.
// PCl5 molar mass 208.5 (vapour density 104.25); N2O4 molar mass 92 (vapour density 46).
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';
import { tidyGens } from '../_util.js';

let _n = 0;
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const mk = (id, level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id, type: 'mcq', level, format: 'single', exams: EX[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (id, level, sub, q, answer, tol, unit, sol, trap) => ({ id, type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
const msq = (id, level, sub, q, options, answer, sol, trap) => ({ id, type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (id, level, sub, A, R, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'assertion', exams: EX[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const mat = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (id, level, sub, group, q, answer, tol, unit, sol, trap) => ({ ...nat(id, level, sub, q, answer, tol, unit, sol, trap), format: 'passage', group });

const RT = (T) => 0.0821 * T;
// gas reactions with change in moles of gas
const RX = [
  ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', -2], ['2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)', -1], ['PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', 1],
  ['N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g)', 1], ['H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', 0], ['CO(g) + 2H<sub>2</sub>(g) &#8652; CH<sub>3</sub>OH(g)', -2], ['2NH<sub>3</sub>(g) &#8652; N<sub>2</sub>(g) + 3H<sub>2</sub>(g)', 2],
];
const UNIT = { '-2': 'L<sup>2</sup> mol<sup>-2</sup>', '-1': 'L mol<sup>-1</sup>', '0': 'no unit', '1': 'mol L<sup>-1</sup>', '2': 'mol<sup>2</sup> L<sup>-2</sup>' };
const UNITP = { '-2': 'atm<sup>-2</sup>', '-1': 'atm<sup>-1</sup>', '0': 'no unit', '1': 'atm', '2': 'atm<sup>2</sup>' };

// shared match helper (pasted into each ext)
const XGR = {};
const M = (id, level, sub, title, l1, l2, map, sol, trap) => {
  const L = 'ABCD', Q = 'pqrst';
  XGR[id] = { title, list1: l1.map((t, i) => `${L[i]}. ${t}`), list2: l2.map((t, i) => `${Q[i]}. ${t}`) };
  const code = (m) => m.map((x, i) => `${L[i]}-${x}`).join(', ');
  const sw = (a, i, j) => { const b = [...a]; [b[i], b[j]] = [b[j], b[i]]; return b; };
  const wr = [sw(map, 0, 1), sw(map, 1, 2), sw(map, 2, 3), sw(map, 0, 3), sw(map, 0, 2)].map(code).filter((c) => c !== code(map));
  return mat(id, level, sub, id, 'Match the entries of List I with those of List II and choose the correct code.', code(map), wr.slice(0, 3), sol, trap);
};
const XI = [
  mk('ce-x01', 2, 'equilibrium constant expression', 'For 4NH<sub>3</sub>(g) + 5O<sub>2</sub>(g) &#8652; 4NO(g) + 6H<sub>2</sub>O(g), the expression for K<sub>c</sub> is', '[NO]<sup>4</sup>[H<sub>2</sub>O]<sup>6</sup> / ([NH<sub>3</sub>]<sup>4</sup>[O<sub>2</sub>]<sup>5</sup>)', ['[NO][H<sub>2</sub>O] / ([NH<sub>3</sub>][O<sub>2</sub>])', '[NH<sub>3</sub>]<sup>4</sup>[O<sub>2</sub>]<sup>5</sup> / ([NO]<sup>4</sup>[H<sub>2</sub>O]<sup>6</sup>)', '[NO]<sup>4</sup>[H<sub>2</sub>O]<sup>6</sup>'], '<p>Products on top, reactants below, each raised to its coefficient. Here water is a gas, so it is included.</p>', 'The reverse (reactants over products) is K for the backward reaction.'),
  nat('ce-x02', 2, 'calculating K<sub>c</sub>', 'For A + B &#8652; C (all in solution) the equilibrium concentrations are [A] = 0.20, [B] = 0.50, [C] = 0.50 mol L<sup>-1</sup>. K<sub>c</sub> in L mol<sup>-1</sup> is', 5, 0, 'L mol<sup>-1</sup>', '<p>K<sub>c</sub> = [C]/([A][B]) = 0.50 / (0.20 &times; 0.50) = 0.50/0.10 = <b>5</b>.</p>'),
  mk('ce-x03', 2, 'K<sub>p</sub> and K<sub>c</sub>', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), K<sub>p</sub> and K<sub>c</sub> are related by', 'K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-2</sup>', ['K<sub>p</sub> = K<sub>c</sub>(RT)<sup>2</sup>', 'K<sub>p</sub> = K<sub>c</sub>(RT)', 'K<sub>p</sub> = K<sub>c</sub>'], '<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup> with &Delta;n<sub>g</sub> = 2 - (1 + 3) = -2.</p>'),
  mk('ce-x04', 2, 'reaction quotient', 'For A + B &#8652; C + D, K<sub>c</sub> = 4. A mixture has [A] = [B] = 0.50 and [C] = [D] = 0.25 mol L<sup>-1</sup>. The mixture', 'moves forward, because Q = 0.25 is less than K<sub>c</sub>', ['moves backward, because Q = 4 is equal to K<sub>c</sub>', 'is at equilibrium, because Q = 0.25', 'moves backward, because Q = 0.25 is less than K<sub>c</sub>'], '<p>Q = (0.25 &times; 0.25)/(0.50 &times; 0.50) = 0.0625/0.25 = 0.25. Since Q &lt; K<sub>c</sub> = 4, more products must form: forward.</p>'),
  nat('ce-x05', 2, 'K<sub>p</sub> and K<sub>c</sub>', '<p>For how many of these equilibria is K<sub>p</sub> equal to K<sub>c</sub>?</p><p>(i) H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI<br>(ii) N<sub>2</sub> + O<sub>2</sub> &#8652; 2NO<br>(iii) PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub><br>(iv) 2NO<sub>2</sub> &#8652; N<sub>2</sub>O<sub>4</sub><br>(v) CO + H<sub>2</sub>O &#8652; CO<sub>2</sub> + H<sub>2</sub> (all gases)</p>', 3, 0, '', '<p>K<sub>p</sub> = K<sub>c</sub> when &Delta;n<sub>g</sub> = 0. (i) 2 - 2 = 0; (ii) 2 - 2 = 0; (iii) +1; (iv) -1; (v) 2 - 2 = 0. So <b>3</b>.</p>'),
  mk('ce-x06', 2, 'dynamic equilibrium', 'Which statement about a chemical equilibrium in a closed vessel is <b>not</b> true?', 'The forward and backward reactions have both stopped', ['The rates of the forward and backward reactions are equal', 'The concentrations of all species stay constant', 'The same equilibrium can be reached from the reactant side or the product side'], '<p>Equilibrium is dynamic: both reactions go on, at the same rate. Only the macroscopic properties (concentration, colour, pressure) stop changing.</p>'),

  nat('ce-x07', 3, 'calculating K<sub>c</sub>', '1.0 mol each of H<sub>2</sub> and I<sub>2</sub> are heated in a 1.0 L vessel. At equilibrium [H<sub>2</sub>] = [I<sub>2</sub>] = 0.22 and [HI] = 1.56 mol L<sup>-1</sup>. K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI is', 50.3, 0.5, '', `<p>K<sub>c</sub> = [HI]<sup>2</sup>/([H<sub>2</sub>][I<sub>2</sub>]) = (1.56)<sup>2</sup>/(0.22 &times; 0.22) = 2.434/0.0484 = <b>${(1.56 ** 2 / 0.22 ** 2).toFixed(1)}</b>.</p>`),
  nat('ce-x08', 3, 'K<sub>p</sub> and K<sub>c</sub>', 'For N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g), K<sub>c</sub> = 4.6 &times; 10<sup>-3</sup> mol L<sup>-1</sup> at 298 K. K<sub>p</sub> in atm is (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)', 0.1125, 0.002, 'atm', `<p>&Delta;n<sub>g</sub> = +1, so K<sub>p</sub> = K<sub>c</sub>RT = 4.6 &times; 10<sup>-3</sup> &times; 0.0821 &times; 298 = 4.6 &times; 10<sup>-3</sup> &times; 24.47 = <b>0.1125 atm</b>.</p>`),
  nat('ce-x09', 3, 'degree of dissociation', 'N<sub>2</sub>O<sub>4</sub> at an initial pressure of 2.0 atm dissociates 25% to NO<sub>2</sub> at constant volume and temperature. K<sub>p</sub> in atm is', 0.667, 0.01, 'atm', '<p>Initial p(N<sub>2</sub>O<sub>4</sub>) = 2.0. Dissociated: 2.0 &times; 0.25 = 0.50 atm.</p><p>p(N<sub>2</sub>O<sub>4</sub>) = 1.50; p(NO<sub>2</sub>) = 2 &times; 0.50 = 1.00 atm.</p><p>K<sub>p</sub> = (1.00)<sup>2</sup>/1.50 = <b>0.667 atm</b>.</p>', 'Each N<sub>2</sub>O<sub>4</sub> gives two NO<sub>2</sub>.'),
  mk('ce-x10', 3, '&Delta;G and K', 'For a reaction at 298 K, &Delta;G&deg; = 0. The equilibrium constant is', '1', ['0', '298', 'infinity'], '<p>&Delta;G&deg; = -RT ln K. If &Delta;G&deg; = 0 then ln K = 0, so K = <b>1</b>.</p>'),
  asr('ce-x11', 3, 'K<sub>p</sub> and K<sub>c</sub>', 'For N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) at 298 K, K<sub>p</sub> is numerically larger than K<sub>c</sub>.', 'K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>, here &Delta;n<sub>g</sub> = +1 and RT (about 24.5 L atm mol<sup>-1</sup>) is greater than 1.', 0, '<p>K<sub>p</sub> = K<sub>c</sub> &times; 24.5. A is true because of the factor RT &gt; 1 and &Delta;n<sub>g</sub> = +1. R gives exactly this reason.</p>'),
  stm('ce-x12', 3, 'dynamic equilibrium', 'At equilibrium the concentrations of reactants and products are equal.', 'At equilibrium the rate of the forward reaction equals the rate of the backward reaction.', 2, '<p>Statement I is false: the concentrations are constant, but usually unequal (their ratio is given by K). Statement II is the correct definition of dynamic equilibrium.</p>'),
  nat('ce-x13', 3, 'ICE table', '1.0 mol each of H<sub>2</sub> and I<sub>2</sub> are placed in a 1.0 L vessel. K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI is 64. Equilibrium [HI] in mol L<sup>-1</sup> is', 1.6, 0.02, 'mol L<sup>-1</sup>', '<p>If x mol of each reacts: [H<sub>2</sub>] = [I<sub>2</sub>] = 1 - x, [HI] = 2x.</p><p>64 = (2x)<sup>2</sup>/(1 - x)<sup>2</sup>, so 8 = 2x/(1 - x) (positive root), giving 8 - 8x = 2x and x = 0.8.</p><p>[HI] = 2x = <b>1.6 mol L<sup>-1</sup></b>.</p>', 'Take the square root of both sides: a perfect square makes this easy.'),
  mk('ce-x14', 3, 'Le Chatelier principle', 'More Cl<sub>2</sub> is added to PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> at equilibrium (constant volume and temperature). At the new equilibrium', 'the amount of PCl<sub>5</sub> is more than before, and K<sub>c</sub> is unchanged', ['the amount of PCl<sub>5</sub> is less than before', 'the amount of Cl<sub>2</sub> returns to its old value', 'K<sub>c</sub> is larger'], '<p>Adding product makes Q &gt; K, so the net reaction goes backward and PCl<sub>5</sub> increases. The net result still has more Cl<sub>2</sub> than before (the shift only uses up part of what was added). K depends only on T.</p>'),
  nat('ce-x15', 3, '&Delta;G and K', 'For a reaction K = 0.040 at 298 K. &Delta;G&deg; in kJ mol<sup>-1</sup> is (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)', 7.97, 0.05, 'kJ mol<sup>-1</sup>', `<p>&Delta;G&deg; = -RT ln K = -(8.314)(298)(ln 0.040) = -2477.6 &times; (-3.219) = +7975 J = <b>+7.97 kJ mol<sup>-1</sup></b>.</p>`),
  mk('ce-x16', 3, 'heterogeneous equilibrium', 'In CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g) at a fixed temperature in a closed vessel, adding more CaO(s) (the solids remain present)', 'does not change the pressure of CO<sub>2</sub>', ['increases the pressure of CO<sub>2</sub>', 'decreases the pressure of CO<sub>2</sub>', 'increases K<sub>p</sub>'], '<p>K<sub>p</sub> = p(CO<sub>2</sub>). Pure solids have constant activity, so their amount does not enter K<sub>p</sub>. At constant T, p(CO<sub>2</sub>) stays at its equilibrium value.</p>'),
  nat('ce-x17', 3, 'heterogeneous equilibrium', 'For Fe<sub>3</sub>O<sub>4</sub>(s) + 4H<sub>2</sub>(g) &#8652; 3Fe(s) + 4H<sub>2</sub>O(g), how many species appear in the expression for K<sub>c</sub>?', 2, 0, '', '<p>K<sub>c</sub> = [H<sub>2</sub>O]<sup>4</sup>/[H<sub>2</sub>]<sup>4</sup>. Only H<sub>2</sub>(g) and H<sub>2</sub>O(g) appear: <b>2</b>.</p>'),
  M('ce-x18', 3, 'K<sub>p</sub> and K<sub>c</sub>', 'Match the equilibrium with the relation between K<sub>p</sub> and K<sub>c</sub>', ['H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', 'N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', 'PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', '2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)'], ['K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-1</sup>', 'K<sub>p</sub> = K<sub>c</sub>(RT)', 'K<sub>p</sub> = K<sub>c</sub>', 'K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-2</sup>'], ['r', 's', 'q', 'p'], '<p>&Delta;n<sub>g</sub>: HI 0 (r); NH<sub>3</sub> -2 (s); PCl<sub>5</sub> +1 (q); SO<sub>3</sub> -1 (p).</p>'),
  PN('ce-x19', 3, 'K<sub>p</sub> of a solid decomposition', 'x1', 'The K<sub>p</sub> of the decomposition at this temperature, in atm<sup>2</sup>, is', 0.09, 0.002, 'atm<sup>2</sup>', '<p>NH<sub>3</sub> and H<sub>2</sub>S are formed in equal amounts, so each has p = 0.60/2 = 0.30 atm.</p><p>K<sub>p</sub> = p(NH<sub>3</sub>) &times; p(H<sub>2</sub>S) = 0.30 &times; 0.30 = <b>0.09 atm<sup>2</sup></b>.</p>'),
  PN('ce-x20', 4, 'common-product effect', 'x1', 'Extra NH<sub>3</sub> is injected, and when equilibrium is restored p(NH<sub>3</sub>) = 0.40 atm. The new p(H<sub>2</sub>S) in atm is', 0.225, 0.005, 'atm', '<p>K<sub>p</sub> is unchanged at 0.09, so p(H<sub>2</sub>S) = 0.09/0.40 = <b>0.225 atm</b>.</p>'),
  P('ce-x21', 3, 'common-product effect', 'x1', 'Compared with the first equilibrium, the mass of solid NH<sub>4</sub>HS in the vessel after the extra NH<sub>3</sub> is injected is', 'greater, because the equilibrium shifts backward', ['smaller, because more NH<sub>3</sub> is available to react', 'the same, because solids do not affect the equilibrium', 'zero, because NH<sub>4</sub>HS is used up'], '<p>The extra NH<sub>3</sub> makes Q = p(NH<sub>3</sub>)p(H<sub>2</sub>S) greater than K<sub>p</sub>, so some NH<sub>3</sub> combines with H<sub>2</sub>S to form more solid. The solid does not appear in K, but its mass still changes.</p>'),

  nat('ce-x22', 4, 'K<sub>p</sub> from mole fractions', 'In an equilibrium mixture for N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> at a total pressure of 10 atm, the mole fractions are N<sub>2</sub> 0.20, H<sub>2</sub> 0.60, NH<sub>3</sub> 0.20. K<sub>p</sub> in atm<sup>-2</sup> is', 0.00926, 0.0002, 'atm<sup>-2</sup>', '<p>Partial pressures: N<sub>2</sub> 2, H<sub>2</sub> 6, NH<sub>3</sub> 2 atm.</p><p>K<sub>p</sub> = p(NH<sub>3</sub>)<sup>2</sup> / (p(N<sub>2</sub>) p(H<sub>2</sub>)<sup>3</sup>) = 4 / (2 &times; 216) = <b>0.00926 atm<sup>-2</sup></b>.</p>'),
  nat('ce-x23', 4, 'ICE table', 'For A(g) &#8652; B(g) + C(g) in a rigid vessel, K<sub>c</sub> = 0.25 mol L<sup>-1</sup>. Starting with 1.0 mol L<sup>-1</sup> of A only, the equilibrium [B] in mol L<sup>-1</sup> is', 0.390, 0.005, 'mol L<sup>-1</sup>', '<p>[B] = [C] = x, [A] = 1 - x. Then x<sup>2</sup>/(1 - x) = 0.25, so x<sup>2</sup> + 0.25x - 0.25 = 0.</p><p>x = (-0.25 + &radic;(0.0625 + 1)) / 2 = (-0.25 + 1.0308)/2 = <b>0.390 mol L<sup>-1</sup></b>.</p>', 'The approximation x &laquo; 1 fails here: solve the quadratic.'),
  nat('ce-x24', 4, 'degree of dissociation', 'For PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g), K<sub>p</sub> = 1.44 atm. At a total equilibrium pressure of 2.56 atm, the percentage of PCl<sub>5</sub> dissociated is', 60, 0, '%', '<p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>), so 1.44(1 - &alpha;<sup>2</sup>) = 2.56&alpha;<sup>2</sup>, so 1.44 = 4.00&alpha;<sup>2</sup>, &alpha;<sup>2</sup> = 0.36, &alpha; = 0.6.</p><p>That is <b>60%</b>.</p>'),
  nat('ce-x25', 4, 'combining equilibria', 'For 2SO<sub>2</sub> + O<sub>2</sub> &#8652; 2SO<sub>3</sub>, K<sub>c</sub> = 100 L mol<sup>-1</sup>. K<sub>c</sub> for SO<sub>2</sub> + &frac12;O<sub>2</sub> &#8652; SO<sub>3</sub> in L<sup>1/2</sup> mol<sup>-1/2</sup> is', 10, 0, '', '<p>Halving the equation takes the square root of K: &radic;100 = <b>10</b>.</p>', 'Dividing K by 2 is wrong; the exponent halves.'),
  mk('ce-x26', 4, 'reaction quotient', 'For N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, K<sub>c</sub> = 0.005 mol L<sup>-1</sup>. In a vessel [N<sub>2</sub>O<sub>4</sub>] = 0.20 and [NO<sub>2</sub>] = 0.05 mol L<sup>-1</sup>. The mixture will', 'form more N<sub>2</sub>O<sub>4</sub>, since Q = 0.0125 &gt; K<sub>c</sub>', ['form more NO<sub>2</sub>, since Q = 0.0125 &gt; K<sub>c</sub>', 'form more N<sub>2</sub>O<sub>4</sub>, since Q = 0.0025 &lt; K<sub>c</sub>', 'stay unchanged, since Q = 0.005'], '<p>Q = [NO<sub>2</sub>]<sup>2</sup>/[N<sub>2</sub>O<sub>4</sub>] = (0.05)<sup>2</sup>/0.20 = 0.0025/0.20 = 0.0125. Since Q &gt; K<sub>c</sub> = 0.005, the net reaction is backward, making N<sub>2</sub>O<sub>4</sub>.</p>', 'Square the NO<sub>2</sub> concentration.'),
  mk('ce-x27', 4, 'effect of pressure', 'For C(s) + CO<sub>2</sub>(g) &#8652; 2CO(g), raising the total pressure by compression at constant temperature', 'shifts the equilibrium towards CO<sub>2</sub>', ['shifts the equilibrium towards CO', 'has no effect, because carbon is a solid', 'increases K<sub>p</sub>'], '<p>Count only gas moles: 1 on the left, 2 on the right. Higher pressure favours fewer gas moles, so the equilibrium moves to the left (CO<sub>2</sub>). Solid carbon is ignored in counting, but the gases are not.</p>'),
  msq('ce-x28', 4, 'Le Chatelier principle', '<p>For N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g), &Delta;H = +57 kJ, which changes increase the fraction of NO<sub>2</sub> at equilibrium?</p>', ['Raising the temperature', 'Adding argon at constant total pressure', 'Adding argon at constant volume', 'Adding a catalyst'], [0, 1], '<p>The forward reaction is endothermic, so heating favours it. Argon at constant p increases V, lowering partial pressures, favouring the side with more moles (NO<sub>2</sub>). Argon at constant V changes no concentration. A catalyst does not shift equilibrium.</p>'),
  msq('ce-x29', 4, 'dynamic equilibrium', '<p>For N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> in a closed vessel at equilibrium, which are correct?</p>', ['The rate of formation of NH<sub>3</sub> equals the rate of its decomposition', 'K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-2</sup>', 'The concentrations of N<sub>2</sub>, H<sub>2</sub> and NH<sub>3</sub> are equal', 'The amount of NH<sub>3</sub> no longer changes'], [0, 1, 3], '<p>A and D describe the dynamic steady state; B is the standard conversion with &Delta;n<sub>g</sub> = -2. Equal concentrations (C) are not required: only the ratio in K is fixed.</p>'),
  msq('ce-x30', 4, 'meaning of K', '<p>Which statements about the equilibrium constant are correct?</p>', ['K does not depend on the initial concentrations', 'K for the reverse reaction is 1/K', 'Doubling every coefficient in the equation doubles K', 'A catalyst increases K'], [0, 1], '<p>K depends on T and on how the equation is written. The reverse reaction has 1/K. Doubling the coefficients squares K (not doubles it). A catalyst changes rates, not K.</p>'),
  nat('ce-x31', 4, 'degree of dissociation', 'N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> is 20% dissociated at a total pressure of 1.0 atm. At the same temperature, the total pressure (in atm) at which it is 50% dissociated is', 0.125, 0.003, 'atm', `<p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 4(0.04)(1)/0.96 = 0.1667 atm.</p><p>For &alpha; = 0.5: P = K<sub>p</sub>(1 - 0.25)/(4 &times; 0.25) = 0.1667 &times; 0.75 = <b>0.125 atm</b>.</p>`),
  nat('ce-x32', 4, 'mole fraction', 'PCl<sub>5</sub> is 60% dissociated at equilibrium (PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>), starting from 1 mol. The mole percent of Cl<sub>2</sub> in the equilibrium mixture is', 37.5, 0.1, '%', '<p>Moles: PCl<sub>5</sub> 0.4, PCl<sub>3</sub> 0.6, Cl<sub>2</sub> 0.6; total 1.6. Mole fraction of Cl<sub>2</sub> = 0.6/1.6 = 0.375, so <b>37.5%</b>.</p>'),
  nat('ce-x33', 4, 'K<sub>p</sub> from partial pressures', 'In a mixture at equilibrium for 2SO<sub>2</sub> + O<sub>2</sub> &#8652; 2SO<sub>3</sub>, the partial pressures are SO<sub>2</sub> 0.20, O<sub>2</sub> 0.50 and SO<sub>3</sub> 2.0 atm. K<sub>p</sub> in atm<sup>-1</sup> is', 200, 0, 'atm<sup>-1</sup>', '<p>K<sub>p</sub> = p(SO<sub>3</sub>)<sup>2</sup>/(p(SO<sub>2</sub>)<sup>2</sup>p(O<sub>2</sub>)) = 4.0/(0.04 &times; 0.50) = 4.0/0.020 = <b>200</b>.</p>'),
  nat('ce-x34', 4, 'K<sub>c</sub> from moles', '2.0 mol of PCl<sub>5</sub> is heated in a 4.0 L vessel and 25% dissociates. K<sub>c</sub> for PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> in mol L<sup>-1</sup> is', 0.0417, 0.0005, 'mol L<sup>-1</sup>', '<p>Moles at equilibrium: PCl<sub>3</sub> = Cl<sub>2</sub> = 0.50; PCl<sub>5</sub> = 1.50. Concentrations (V = 4.0 L): 0.125, 0.125, 0.375.</p><p>K<sub>c</sub> = 0.125 &times; 0.125/0.375 = <b>0.0417</b>. Because &Delta;n<sub>g</sub> = +1, you must divide moles by V.</p>', 'Using moles directly gives 0.167, which is wrong.'),
  nat('ce-x35', 4, 'van&rsquo;t Hoff equation', 'For N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, &Delta;H&deg; = +57.2 kJ mol<sup>-1</sup> and K = 0.147 at 298 K. K at 350 K (taking &Delta;H&deg; constant) is', 4.54, 0.1, '', `<p>ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H&deg;/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (57200/8.314)(1/298 - 1/350) = 6880 &times; 4.986 &times; 10<sup>-4</sup> = 3.430.</p><p>K<sub>2</sub> = 0.147 &times; e<sup>3.430</sup> = 0.147 &times; 30.9 = <b>4.54</b>.</p>`),
  nat('ce-x36', 4, 'heterogeneous equilibrium', 'K<sub>p</sub> for CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g) is 0.20 atm at 1000 K. Excess CaCO<sub>3</sub> is heated in a 10 L vessel at 1000 K. The moles of CO<sub>2</sub> present at equilibrium are (R = 0.0821)', 0.0244, 0.0005, 'mol', '<p>p(CO<sub>2</sub>) = K<sub>p</sub> = 0.20 atm. n = pV/RT = (0.20 &times; 10)/(0.0821 &times; 1000) = 2.0/82.1 = <b>0.0244 mol</b>.</p>'),
  mk('ce-x37', 4, 'temperature effect', 'For a reaction, K = 0.5 at 300 K and K = 5.0 at 400 K. The reaction is', 'endothermic, since K increases with T', ['exothermic, since K increases with T', 'endothermic, since K decreases with T', 'neither: K never depends on T'], '<p>By Le Chatelier (and the van&rsquo;t Hoff equation), K rises with T only if &Delta;H &gt; 0, i.e. the reaction absorbs heat. It is endothermic.</p>'),
  asr('ce-x38', 4, 'Haber process', 'In the Haber process a pressure of about 200 atm is used, yet much higher pressures are avoided.', 'A higher pressure increases the value of the equilibrium constant K<sub>p</sub>.', 2, '<p>A is true: more pressure favours NH<sub>3</sub> (fewer moles), but very high pressure makes vessels expensive and unsafe. R is false: K<sub>p</sub> depends only on temperature. Pressure changes the position of equilibrium, not K.</p>'),
  { ...mk('ce-x39', 4, 'mixed counting', '<p>How many of the following are correct?</p><p>(1) K<sub>c</sub> changes when a catalyst is added.<br>(2) K<sub>c</sub> changes when T changes.<br>(3) The yield of NH<sub>3</sub> rises when NH<sub>3</sub> is removed continuously.<br>(4) For N<sub>2</sub> + O<sub>2</sub> &#8652; 2NO, changing the volume at constant T shifts the equilibrium.</p>', '2', ['1', '3', '4'], '<p>(1) false. (2) true. (3) true: removing product keeps Q &lt; K. (4) false: &Delta;n<sub>g</sub> = 0, so volume changes do not shift it. Two are correct: <b>2</b>.</p>'), format: 'statements' },
  M('ce-x40', 4, 'effect of compression', 'Match the equilibrium with what happens when the mixture is compressed to half its volume at constant temperature', ['N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g)', 'H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', '2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)', 'CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g)'], ['No shift', 'Shifts left; every gas concentration ends higher than before', 'Shifts left; the gas concentration returns to its old value', 'Shifts right'], ['q', 'p', 's', 'r'], '<p>A: more gas moles on the right, so it shifts left, but both gases end at higher concentrations (q). B: &Delta;n<sub>g</sub> = 0, no shift (p). C: fewer moles on the right, so it shifts right (s). D: shifts left, but K<sub>p</sub> = p(CO<sub>2</sub>) fixes the CO<sub>2</sub> pressure at its old value (r).</p>'),
  M('ce-x41', 3, 'meaning of K', 'Match the value with its meaning', ['K &gt;&gt; 1', 'K &lt;&lt; 1', 'K about 1', 'Q &gt; K'], ['Net backward reaction', 'Comparable amounts of reactants and products', 'Reaction goes nearly to completion', 'Hardly any product forms'], ['r', 's', 'q', 'p'], '<p>K &gt;&gt; 1: products dominate (r). K &lt;&lt; 1: reactants dominate (s). K about 1: comparable amounts (q). Q &gt; K: too many products, so the net reaction is backward (p).</p>'),
  M('ce-x42', 5, 'degree of dissociation', 'Match the dissociation with K<sub>p</sub> in terms of &alpha; (degree of dissociation) and total pressure P at equilibrium', ['AB(g) &#8652; A(g) + B(g)', 'A<sub>2</sub>(g) &#8652; 2A(g)', '2AB(g) &#8652; A<sub>2</sub>(g) + B<sub>2</sub>(g)', 'A(g) &#8652; B(g)'], ['&alpha;/(1 - &alpha;)', '&alpha;<sup>2</sup>/(4(1 - &alpha;)<sup>2</sup>)', '4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>)', '&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>)', '&alpha;<sup>2</sup>P/(1 - &alpha;)<sup>2</sup>'], ['s', 'r', 'q', 'p'], '<p>Start with 1 mol AB: AB (1 - &alpha;), A &alpha;, B &alpha;, total 1 + &alpha;, so K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) (s). A<sub>2</sub>: A<sub>2</sub> (1 - &alpha;), A 2&alpha;, total 1 + &alpha;: 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) (r). 2AB (start 2 mol): AB 2(1 - &alpha;), A<sub>2</sub> &alpha;, B<sub>2</sub> &alpha;, total 2; &Delta;n<sub>g</sub> = 0 so P cancels: &alpha;<sup>2</sup>/(4(1 - &alpha;)<sup>2</sup>) (q). A &#8652; B: &alpha;/(1 - &alpha;) (p). The fifth entry is a distractor.</p>'),
  PN('ce-x43', 4, 'calculating K<sub>c</sub>', 'x2', 'K<sub>c</sub> for 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> at 700 K is', 0.0156, 0.0003, '', '<p>[HI] = 0.80, [H<sub>2</sub>] = [I<sub>2</sub>] = 0.10 (V = 1 L). K<sub>c</sub> = (0.10 &times; 0.10)/(0.80)<sup>2</sup> = 0.010/0.64 = <b>0.0156</b>.</p>'),
  P('ce-x44', 4, 'degree of dissociation', 'x2', 'If 2.0 mol of HI is heated in the same 1.0 L vessel at the same temperature, the percentage dissociated will be', '20%, the same as before', ['10%', '40%', '5%'], '<p>For 2HI &#8652; H<sub>2</sub> + I<sub>2</sub>, &Delta;n<sub>g</sub> = 0, so &alpha; does not depend on concentration or pressure: K = (&alpha;/2)<sup>2</sup>/(1 - &alpha;)<sup>2</sup>. &alpha; stays 20%.</p>'),
  PN('ce-x45', 4, 'reversing an equation', 'x2', 'K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI at the same temperature is', 64, 0.5, '', '<p>It is the reverse reaction, so K<sub>c</sub> = 1/0.015625 = <b>64</b>.</p>'),

  msq('ce-x46', 5, 'heterogeneous equilibrium', '<p>NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g) is at equilibrium in a closed vessel with solid present. The volume is doubled at constant temperature (some solid still remains). Which stay the same?</p>', ['K<sub>p</sub>', 'p(NH<sub>3</sub>)', 'The total pressure', 'The moles of NH<sub>3</sub>(g)'], [0, 1, 2], '<p>K<sub>p</sub> = p(NH<sub>3</sub>)p(H<sub>2</sub>S) is fixed by T, and the two pressures are equal, so each returns to the same value as more solid decomposes. The total pressure is the same, but the vessel is larger, so the moles of gas are greater: D is false.</p>'),
  msq('ce-x47', 5, 'reaction quotient', '<p>A(g) &#8652; 2B(g) is at equilibrium in a cylinder. The volume is suddenly halved at constant temperature. Which are correct?</p>', ['Immediately after compression Q is greater than K<sub>c</sub>', 'The net reaction then goes backward', 'K<sub>c</sub> is halved', 'At the new equilibrium [B] is more than twice its old value'], [0, 1], '<p>Halving the volume doubles every concentration: Q = (2b)<sup>2</sup>/(2a) = 2Q<sub>old</sub> = 2K &gt; K, so the net reaction goes backward. K depends only on T. The shift consumes some B, so the new [B] is more than the old one but less than twice it: D is false.</p>'),
  msq('ce-x48', 5, 'K<sub>p</sub> and K<sub>c</sub>', '<p>For 2NO<sub>2</sub>(g) &#8652; N<sub>2</sub>O<sub>4</sub>(g) at 300 K, which are correct?</p>', ['K<sub>p</sub> = K<sub>c</sub>/(RT)', 'K<sub>p</sub> is numerically smaller than K<sub>c</sub>', 'The two constants are expressed in different units', 'K<sub>p</sub> = K<sub>c</sub> at every temperature'], [0, 1, 2], '<p>&Delta;n<sub>g</sub> = -1, so K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-1</sup>; RT = 24.6 &gt; 1, so K<sub>p</sub> &lt; K<sub>c</sub> in numbers. K<sub>c</sub> has L mol<sup>-1</sup> and K<sub>p</sub> has atm<sup>-1</sup>. They are equal only when &Delta;n<sub>g</sub> = 0.</p>'),
  msq('ce-x49', 5, 'catalyst', '<p>A catalyst is added to a reaction at equilibrium. Which are correct?</p>', ['It increases K', 'It lowers the activation energy of the forward and backward reactions by the same amount', 'It changes the composition at equilibrium', 'It shortens the time needed to reach equilibrium'], [1, 3], '<p>A catalyst provides a new path with a lower barrier for both directions, by the same amount, so the ratio of rate constants (K) does not change and neither does the equilibrium composition. It only reaches equilibrium sooner.</p>'),
  msq('ce-x50', 5, 'degree of dissociation', '<p>Which statements about the degree of dissociation (&alpha;) are correct?</p>', ['PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>: &alpha; decreases when the total pressure is raised', '2HI &#8652; H<sub>2</sub> + I<sub>2</sub>: &alpha; does not depend on pressure', 'N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>: &alpha; increases when argon is added at constant volume', '2NH<sub>3</sub> &#8652; N<sub>2</sub> + 3H<sub>2</sub>: &alpha; decreases when the pressure is raised'], [0, 1, 3], '<p>Whenever dissociation increases the number of gas moles (A, D) higher pressure lowers &alpha;. If &Delta;n<sub>g</sub> = 0 (B), pressure does not matter. Argon at constant volume does not change partial pressures, so &alpha; is unchanged (C is false).</p>'),
  msq('ce-x51', 5, 'reaction quotient', '<p>For A + B &#8652; C, K<sub>c</sub> = 10 L mol<sup>-1</sup> at some temperature. A mixture has [A] = [B] = 0.10 and [C] = 0.20 mol L<sup>-1</sup>. Which are correct?</p>', ['Q = 20 L mol<sup>-1</sup>', 'The net reaction proceeds backward', '&Delta;G is positive', '&Delta;G&deg; is positive'], [0, 1, 2], '<p>Q = 0.20/(0.10 &times; 0.10) = 20 &gt; K = 10. The net reaction goes backward, and &Delta;G = RT ln(Q/K) = RT ln 2 &gt; 0. But K &gt; 1 means &Delta;G&deg; = -RT ln K &lt; 0, so D is false.</p>'),
  msq('ce-x52', 5, 'contact process', '<p>For 2SO<sub>2</sub> + O<sub>2</sub> &#8652; 2SO<sub>3</sub>, &Delta;H &lt; 0, which raise the equilibrium yield of SO<sub>3</sub>?</p>', ['Using a V<sub>2</sub>O<sub>5</sub> catalyst', 'Using an excess of air', 'Removing SO<sub>3</sub> as it forms', 'Raising the temperature'], [1, 2], '<p>Excess O<sub>2</sub> and removal of product keep Q &lt; K. The catalyst only speeds the approach. Heating an exothermic reaction lowers K and the yield.</p>'),
  nat('ce-x53', 4, 'ICE table', 'For A(g) + B(g) &#8652; C(g) + D(g), K<sub>c</sub> = 9. 1.0 mol each of A and B are placed in a 1.0 L vessel. The percentage of A converted at equilibrium is', 75, 0, '%', '<p>x/(1 - x) = &radic;9 = 3 (since [C] = [D] = x and [A] = [B] = 1 - x), so x = 0.75: <b>75%</b>.</p>'),
  nat('ce-x54', 5, 'degree of dissociation', 'For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>, K<sub>p</sub> = 1.0 atm. At what total pressure (atm) is PCl<sub>5</sub> 50% dissociated?', 3, 0, 'atm', '<p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 0.25P/0.75 = P/3. Setting this to 1.0 gives P = <b>3 atm</b>.</p>'),
  nat('ce-x55', 5, 'K<sub>p</sub>', 'For N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, K<sub>p</sub> = 20 atm at a certain temperature. At equilibrium p(N<sub>2</sub>O<sub>4</sub>) = 0.20 atm. p(NO<sub>2</sub>) in atm is', 2, 0, 'atm', '<p>K<sub>p</sub> = p(NO<sub>2</sub>)<sup>2</sup>/p(N<sub>2</sub>O<sub>4</sub>), so p(NO<sub>2</sub>)<sup>2</sup> = 20 &times; 0.20 = 4 and p(NO<sub>2</sub>) = <b>2 atm</b>.</p>'),
  nat('ce-x56', 5, 'ICE table', '2.0 mol each of A and B are mixed in a 2.0 L flask: A(g) + B(g) &#8652; 2C(g), K<sub>c</sub> = 4. The moles of C at equilibrium are', 2, 0, 'mol', '<p>&Delta;n<sub>g</sub> = 0, so volume cancels. If x mol of each reacts, K = (2x)<sup>2</sup>/(2 - x)<sup>2</sup> = 4, so 2x/(2 - x) = 2 and x = 1. C = 2x = <b>2 mol</b>.</p>'),
  asr('ce-x57', 5, 'inert gas', 'For A(g) &#8652; 2B(g), adding an inert gas at constant total pressure increases the amount of B at equilibrium without changing K<sub>c</sub>.', 'Adding the inert gas at constant pressure increases the volume, lowering the partial pressures and favouring the side with more gas moles.', 0, '<p>Volume increases, so every partial pressure drops, and the system moves towards the side with more moles (B). K depends only on T. Both true, R explains A.</p>'),
  { ...mk('ce-x58', 5, 'mixed counting', '<p>How many are correct?</p><p>(1) K depends only on temperature (for a given equation).<br>(2) For an exothermic reaction K at a higher T is smaller.<br>(3) Doubling the volume of a closed vessel always shifts equilibrium towards the side with more gas moles, whatever the reaction.<br>(4) The reaction quotient Q is never negative but can be zero.</p>', '3', ['1', '2', '4'], '<p>(1) true. (2) true. (3) false: if &Delta;n<sub>g</sub> = 0 there is no shift. (4) true: with no product present Q = 0. So three: <b>3</b>.</p>'), format: 'statements' },
  M('ce-x59', 4, 'Le Chatelier principle', 'For 2SO<sub>2</sub> + O<sub>2</sub> &#8652; 2SO<sub>3</sub> (&Delta;H &lt; 0) at equilibrium, match the change with the result', ['Add O<sub>2</sub> at constant volume', 'Add SO<sub>3</sub> at constant volume', 'Add argon at constant volume', 'Raise the temperature'], ['No shift', 'Shifts left; K decreases', 'Shifts right; K unchanged', 'Shifts left; K unchanged'], ['r', 's', 'p', 'q'], '<p>A: more reactant, so it shifts right; K unchanged (r). B: more product, so it shifts left; K unchanged (s). C: concentrations do not change, no shift (p). D: the reaction is exothermic, so heating shifts it left and lowers K (q).</p>'),
  M('ce-x60', 4, 'combining equilibria', 'At equilibrium for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, [H<sub>2</sub>] = [I<sub>2</sub>] = 0.10 and [HI] = 0.80 mol L<sup>-1</sup>. Match the equation with its K<sub>c</sub>', ['H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI', '2HI &#8652; H<sub>2</sub> + I<sub>2</sub>', '&frac12;H<sub>2</sub> + &frac12;I<sub>2</sub> &#8652; HI', '2H<sub>2</sub> + 2I<sub>2</sub> &#8652; 4HI'], ['8', '4096', '1/64', '64', '0.125'], ['s', 'r', 'p', 'q'], '<p>K<sub>c</sub> = 0.80<sup>2</sup>/0.10<sup>2</sup> = 64 for the first equation (s). Reverse: 1/64 (r). Half the coefficients: &radic;64 = 8 (p). Double the coefficients: 64<sup>2</sup> = 4096 (q).</p>'),
  M('ce-x61', 5, 'reaction quotient', 'For A(g) &#8652; 2B(g) at equilibrium, match the sudden change with what happens to Q (before any shift)', ['Volume halved', 'Volume doubled', 'Argon added at constant volume', 'Concentration of B doubled by adding B'], ['Q becomes 4 times', 'Q unchanged', 'Q doubles', 'Q halves'], ['r', 's', 'q', 'p'], '<p>Q = [B]<sup>2</sup>/[A]. Halving V doubles both concentrations: Q becomes (2b)<sup>2</sup>/(2a) = 2 times (r). Doubling V: each concentration halves, so Q = (b/2)<sup>2</sup>/(a/2) = Q/2 (s). Argon at constant V changes nothing (q). Doubling [B] alone makes Q 4 times (p).</p>'),
  M('ce-x62', 3, 'combining equilibria', 'For N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> with equilibrium constant K, match the equation with its constant', ['2N<sub>2</sub> + 6H<sub>2</sub> &#8652; 4NH<sub>3</sub>', '&frac12;N<sub>2</sub> + 3/2H<sub>2</sub> &#8652; NH<sub>3</sub>', '2NH<sub>3</sub> &#8652; N<sub>2</sub> + 3H<sub>2</sub>', 'NH<sub>3</sub> &#8652; &frac12;N<sub>2</sub> + 3/2H<sub>2</sub>'], ['1/K', 'K<sup>2</sup>', '1/&radic;K', '&radic;K'], ['q', 's', 'p', 'r'], '<p>Double the equation: K<sup>2</sup> (q). Halve it: &radic;K (s). Reverse it: 1/K (p). Halve and reverse: 1/&radic;K (r).</p>'),
  nat('ce-x63', 5, 'ICE table', 'PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> has K<sub>c</sub> = 0.50 mol L<sup>-1</sup>. A 1.0 L vessel starts with 1.0 mol PCl<sub>5</sub> and 0.50 mol Cl<sub>2</sub>. The equilibrium [PCl<sub>3</sub>] in mol L<sup>-1</sup> is', 0.366, 0.005, 'mol L<sup>-1</sup>', '<p>Let [PCl<sub>3</sub>] = x. Then [Cl<sub>2</sub>] = 0.50 + x and [PCl<sub>5</sub>] = 1.0 - x.</p><p>x(0.50 + x)/(1.0 - x) = 0.50, so x<sup>2</sup> + 0.50x = 0.50 - 0.50x, so x<sup>2</sup> + x - 0.50 = 0.</p><p>x = (-1 + &radic;3)/2 = <b>0.366 mol L<sup>-1</sup></b>.</p>'),
  nat('ce-x64', 4, '&Delta;G and K', 'For a reaction &Delta;G&deg; = +10.0 kJ mol<sup>-1</sup> at 400 K. K at this temperature is (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)', 0.0495, 0.001, '', '<p>ln K = -&Delta;G&deg;/RT = -10000/(8.314 &times; 400) = -3.007, so K = e<sup>-3.007</sup> = <b>0.0495</b>.</p>'),
];
const XGR2 = {
  x1: { title: 'Solid ammonium hydrogen sulphide', passage: '<p>Solid NH<sub>4</sub>HS is placed in an evacuated vessel at a fixed temperature: NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g). At equilibrium the total pressure is <b>0.60 atm</b> and solid is still present.</p>' },
  x2: { title: 'Hydrogen iodide at 700 K', passage: '<p>1.0 mol of HI is heated in a closed 1.0 L vessel at 700 K until 2HI(g) &#8652; H<sub>2</sub>(g) + I<sub>2</sub>(g) is at equilibrium. 20% of the HI has dissociated.</p>' },
};
Object.assign(XGR, XGR2);
const sg = (x) => (x > 0 ? '+' : '') + x;
const XGN = [
  { id: 'ce-g17', type: 'nat', level: 4, exams: EX[4], sub: 'degree of dissociation',
    make(rng) {
      const a = choose(rng, [0.2, 0.25, 0.3, 0.4, 0.5, 0.6]); const P = choose(rng, [0.5, 1, 2, 4]);
      const Kp = a * a * P / (1 - a * a); const ans = +Kp.toPrecision(3);
      return { q: `PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is ${a * 100}% dissociated at a total equilibrium pressure of ${P} atm. Find K<sub>p</sub> in atm.`, answer: ans, tol: Math.max(0.002, ans * 0.01), unit: 'atm', a, P,
        sol: `<p>Start with 1 mol: PCl<sub>5</sub> ${(1 - a).toFixed(2)}, PCl<sub>3</sub> ${a}, Cl<sub>2</sub> ${a}; total ${(1 + a).toFixed(2)}.</p><p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = (${a})<sup>2</sup>(${P})/(1 - ${(a * a).toFixed(4)}) = <b>${ans} atm</b>.</p>` };
    }, verify: (p) => p.a * p.a * p.P / (1 - p.a * p.a) },
  { id: 'ce-g18', type: 'nat', level: 4, exams: EX[4], sub: 'degree of dissociation',
    make(rng) {
      const a = choose(rng, [0.2, 0.25, 0.4, 0.5, 0.6, 0.8]); const P = choose(rng, [1, 2, 4, 5]);
      const Kp = +(a * a * P / (1 - a * a)).toPrecision(3); const ans = 100 * Math.sqrt(Kp / (Kp + P));
      return { q: `For A(g) &#8652; B(g) + C(g), K<sub>p</sub> = ${Kp} atm. Starting from pure A, find the percentage of A dissociated at a total equilibrium pressure of ${P} atm.`, answer: +ans.toFixed(1), tol: 0.5, unit: '%', Kp, P,
        sol: `<p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>), so &alpha;<sup>2</sup> = K<sub>p</sub>/(K<sub>p</sub> + P) = ${Kp}/${(Kp + P).toFixed(3)} = ${(Kp / (Kp + P)).toFixed(4)}.</p><p>&alpha; = ${Math.sqrt(Kp / (Kp + P)).toFixed(3)}, which is <b>${ans.toFixed(1)}%</b>.</p>` };
    }, verify: (p) => 100 * Math.sqrt(p.Kp / (p.Kp + p.P)) },
  { id: 'ce-g19', type: 'nat', level: 4, exams: EX[4], sub: 'van&rsquo;t Hoff equation',
    make(rng) {
      const H = pick(rng, 40, 120, 10); const T1 = choose(rng, [298, 300, 350]); const T2 = T1 + choose(rng, [30, 50, 100]); const K1 = choose(rng, [0.01, 0.05, 0.2, 1, 2]);
      const K2 = K1 * Math.exp(H * 1000 / 8.314 * (1 / T1 - 1 / T2)); const ans = +K2.toPrecision(3);
      return { q: `For an endothermic reaction &Delta;H&deg; = +${H} kJ mol<sup>-1</sup> and K = ${K1} at ${T1} K. Find K at ${T2} K, taking &Delta;H&deg; as constant. (R = 8.314)`, answer: ans, tol: ans * 0.02, H, T1, T2, K1,
        sol: `<p>ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H&deg;/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (${H * 1000}/8.314)(1/${T1} - 1/${T2}) = ${(H * 1000 / 8.314 * (1 / T1 - 1 / T2)).toFixed(3)}.</p><p>K<sub>2</sub> = ${K1} &times; e<sup>${(H * 1000 / 8.314 * (1 / T1 - 1 / T2)).toFixed(3)}</sup> = <b>${fmt(ans, 3)}</b>.</p>` };
    }, verify: (p) => p.K1 * Math.exp(p.H * 1000 / 8.314 * (1 / p.T1 - 1 / p.T2)) },
  { id: 'ce-g20', type: 'nat', level: 4, exams: EX[4], sub: 'ICE table',
    make(rng) {
      const f = choose(rng, [0.5, 0.6, 0.75, 0.8]); const K = +(f * f / ((1 - f) * (1 - f))).toFixed(4); const c = choose(rng, [0.5, 1, 2]);
      return { q: `A(g) + B(g) &#8652; C(g) + D(g) has K<sub>c</sub> = ${K}. ${c} mol each of A and B are placed in a 1.0 L vessel. What percentage of A has reacted at equilibrium?`, answer: f * 100, tol: 0.5, unit: '%', K, c, f,
        sol: `<p>K<sub>c</sub> = x<sup>2</sup>/(${c} - x)<sup>2</sup>, so x/(${c} - x) = &radic;${K} = ${Math.sqrt(K).toFixed(3)}.</p><p>x = ${c} &times; ${f} = ${(c * f).toFixed(3)}, which is <b>${f * 100}%</b> of A. (The initial amount cancels because &Delta;n<sub>g</sub> = 0.)</p>` };
    }, verify: (p) => 100 * Math.sqrt(p.K) / (1 + Math.sqrt(p.K)) },
  { id: 'ce-g21', type: 'mcq', level: 3, exams: EX[3], sub: 'reaction quotient',
    make(rng) {
      const K = choose(rng, [0.5, 2, 4, 10, 25]); const a = pick(rng, 0.1, 0.5, 0.1); let c = pick(rng, 0.1, 0.9, 0.1);
      if (Math.abs(c * c / (a * a) - K) < 1e-9) c = +(c + 0.1).toFixed(1);
      const right = c * c / (a * a) < K ? 'forward' : 'backward';
      const { options, answer } = shuffleOpts(rng, right, ['forward', 'backward', 'neither: it is at equilibrium', 'in both directions equally'].filter((x) => x !== right));
      return { q: `A + B &#8652; C + D, K<sub>c</sub> = ${K}. A mixture has [A] = [B] = ${a} and [C] = [D] = ${c} mol L<sup>-1</sup>. The net reaction goes`, options, answer, K, a, c, Q: c * c / (a * a),
        sol: `<p>Q = [C][D]/([A][B]) = ${c} &times; ${c} / (${a} &times; ${a}) = ${(c * c / (a * a)).toFixed(3)}.</p><p>Q ${c * c / (a * a) < K ? '&lt;' : '&gt;'} K<sub>c</sub> = ${K}, so the net reaction goes <b>${c * c / (a * a) < K ? 'forward' : 'backward'}</b>.</p>` };
    }, verify: (p) => p.answer },
  { id: 'ce-g22', type: 'mcq', level: 4, exams: EX[4], sub: 'Le Chatelier principle',
    make(rng) {
      const R = [['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', -2, -92], ['N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g)', 1, 57], ['H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', 0, -10], ['PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', 1, 93], ['2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)', -1, -198]];
      const r = choose(rng, R); const ch = choose(rng, ['compression', 'heating', 'argon at constant volume']);
      const toward = ch === 'compression' ? (r[1] < 0 ? 'products' : r[1] > 0 ? 'reactants' : 'none') : ch === 'heating' ? (r[2] > 0 ? 'products' : 'reactants') : 'none';
      const right = toward === 'products' ? 'towards the products' : toward === 'reactants' ? 'towards the reactants' : 'no shift';
      const { options, answer } = shuffleOpts(rng, right, ['towards the products', 'towards the reactants', 'no shift', 'cannot be decided'].filter((x) => x !== right));
      return { q: `For ${r[0]}, &Delta;H = ${sg(r[2])} kJ mol<sup>-1</sup>. The equilibrium mixture is subjected to ${ch}. The position of equilibrium moves`, options, answer, r, ch,
        sol: `<p>${ch === 'compression' ? `Gas moles: &Delta;n<sub>g</sub> = ${r[1]}. Higher pressure favours the side with fewer gas moles${r[1] === 0 ? ', but both sides are equal' : ''}.` : ch === 'heating' ? `The reaction is ${r[2] > 0 ? 'endothermic, so heat favours the forward reaction' : 'exothermic, so heat favours the backward reaction'}.` : 'Argon at constant volume leaves all partial pressures unchanged.'}</p><p>Answer: <b>${right}</b>.</p>` };
    }, verify: (p) => p.answer },
  { id: 'ce-g23', type: 'nat', level: 3, exams: EX[3], sub: 'heterogeneous equilibrium',
    make(rng) {
      const P = pick(rng, 0.2, 1.2, 0.1);
      const Kp = (P / 2) ** 2; const ans = +Kp.toFixed(4);
      return { q: `Solid NH<sub>4</sub>HS decomposes to NH<sub>3</sub>(g) + H<sub>2</sub>S(g) in an evacuated vessel. At equilibrium the total pressure is ${P} atm. Find K<sub>p</sub> in atm<sup>2</sup>.`, answer: ans, tol: Math.max(0.0005, ans * 0.01), unit: 'atm<sup>2</sup>', P,
        sol: `<p>The gases are formed in equal amounts, so each has p = ${P}/2 = ${P / 2} atm.</p><p>K<sub>p</sub> = (${P / 2})<sup>2</sup> = <b>${ans} atm<sup>2</sup></b>.</p>` };
    }, verify: (p) => (p.P / 2) * (p.P / 2) },
  { id: 'ce-g24', type: 'nat', level: 4, exams: EX[4], sub: 'K<sub>c</sub> from moles',
    make(rng) {
      const n = choose(rng, [1, 2, 4]); const V = choose(rng, [2, 4, 5, 10]); const a = choose(rng, [0.2, 0.25, 0.4, 0.5]);
      const Kc = n * a * a / (V * (1 - a)); const ans = +Kc.toPrecision(3);
      return { q: `${n} mol of PCl<sub>5</sub> is heated in a ${V} L vessel and ${a * 100}% dissociates (PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>). Find K<sub>c</sub> in mol L<sup>-1</sup>.`, answer: ans, tol: Math.max(0.0003, ans * 0.01), unit: 'mol L<sup>-1</sup>', n, V, a,
        sol: `<p>Moles: PCl<sub>3</sub> = Cl<sub>2</sub> = ${(n * a).toFixed(3)}; PCl<sub>5</sub> = ${(n * (1 - a)).toFixed(3)}. Divide by V = ${V} L.</p><p>K<sub>c</sub> = (${(n * a / V).toFixed(4)})<sup>2</sup> / ${(n * (1 - a) / V).toFixed(4)} = <b>${fmt(ans, 3)}</b>.</p>` };
    }, verify: (p) => p.n * p.a * p.a / (p.V * (1 - p.a)) },
  { id: 'ce-g25', type: 'nat', level: 3, exams: EX[3], sub: '&Delta;G and K',
    make(rng) {
      const G = pick(rng, -20, 20, 2.5); const T = choose(rng, [298, 300, 350, 400]);
      const K = Math.exp(-G * 1000 / (8.314 * T)); const ans = +K.toPrecision(3);
      return { q: `A reaction has &Delta;G&deg; = ${G} kJ mol<sup>-1</sup> at ${T} K. Find the equilibrium constant K. (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)`, answer: ans, tol: ans * 0.02, G, T,
        sol: `<p>ln K = -&Delta;G&deg;/RT = -(${G * 1000})/(8.314 &times; ${T}) = ${(-G * 1000 / (8.314 * T)).toFixed(3)}.</p><p>K = <b>${fmt(ans, 3)}</b>.</p>` };
    }, verify: (p) => Math.exp(-p.G * 1000 / (8.314 * p.T)) },
  { id: 'ce-g26', type: 'nat', level: 5, exams: EX[5], sub: 'K<sub>p</sub> from mole fractions',
    make(rng) {
      const xN = pick(rng, 0.1, 0.3, 0.05); const xA = pick(rng, 0.1, 0.4, 0.05); const xH = +(1 - xN - xA).toFixed(2); const P = choose(rng, [10, 20, 50]);
      const Kp = (xA * P) ** 2 / ((xN * P) * (xH * P) ** 3); const ans = +Kp.toPrecision(3);
      return { q: `At ${P} atm total pressure an equilibrium mixture for N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> has mole fractions N<sub>2</sub> ${xN}, NH<sub>3</sub> ${xA} and H<sub>2</sub> ${xH}. Find K<sub>p</sub> in atm<sup>-2</sup>.`, answer: ans, tol: ans * 0.02, xN, xA, xH, P,
        sol: `<p>Partial pressures: N<sub>2</sub> ${(xN * P).toFixed(2)}, H<sub>2</sub> ${(xH * P).toFixed(2)}, NH<sub>3</sub> ${(xA * P).toFixed(2)} atm.</p><p>K<sub>p</sub> = p(NH<sub>3</sub>)<sup>2</sup>/(p(N<sub>2</sub>)p(H<sub>2</sub>)<sup>3</sup>) = <b>${fmt(ans, 3)} atm<sup>-2</sup></b>.</p>` };
    }, verify: (p) => (p.xA * p.P) ** 2 / ((p.xN * p.P) * (p.xH * p.P) ** 3) },
];

// ---------------------------------------------------------------- Level 5 round (added 2026-11-22)
const V5P = 'ce';
const V5I = [], V5GR = {}, V5G = []; let _v5 = 0, _v5pos = 0;
const V5EX = ['jee-adv'];
const V5A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const V5S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const v5id = () => `${V5P}-v5${String(++_v5).padStart(2, '0')}`;
const v5opts = (right, wrongs) => { const pos = (_v5pos++) % 4; const options = [...wrongs]; options.splice(pos, 0, right); return { options, answer: pos }; };
const v5single = (sub, q, right, wrongs, sol, trap, format = 'single', group) => { const o = v5opts(right, wrongs); const it = { id: v5id(), type: 'mcq', level: 5, format, exams: V5EX, sub, q, options: o.options, answer: o.answer, sol, ...(trap ? { trap } : {}), ...(group ? { group } : {}) }; V5I.push(it); return it; };
const v5nat = (sub, q, answer, tol, unit, sol, trap, format, group) => { V5I.push({ id: v5id(), type: 'nat', level: 5, format: format || (tol === 0 ? 'integer' : 'numeric'), exams: V5EX, sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(group ? { group } : {}) }); };
const v5msq = (sub, q, options, answer, sol, trap) => { V5I.push({ id: v5id(), type: 'msq', level: 5, format: 'multi', exams: V5EX, sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const v5fixed = (sub, q, options, answer, sol, trap, format) => { V5I.push({ id: v5id(), type: 'mcq', level: 5, format, exams: V5EX, sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const v5asr = (sub, A, R, answer, sol, trap) => v5fixed(sub, `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, V5A4, answer, sol, trap, 'assertion');
const v5stm = (sub, s1, s2, answer, sol, trap) => v5fixed(sub, `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, V5S4, answer, sol, trap, 'statements');
const v5match = (sub, title, l1, l2, map, sol, trap) => {
  const gid = `v5m${Object.keys(V5GR).length + 1}`; const L = 'ABCD', Q = 'pqrst';
  V5GR[gid] = { title, list1: l1.map((t, i) => `${L[i]}. ${t}`), list2: l2.map((t, i) => `${Q[i]}. ${t}`) };
  const code = (m) => m.map((x, i) => `${L[i]}-${x}`).join(', ');
  const sw = (a, i, j) => { const b = [...a]; [b[i], b[j]] = [b[j], b[i]]; return b; };
  const wr = [sw(map, 0, 1), sw(map, 1, 2), sw(map, 2, 3), sw(map, 0, 3), sw(map, 0, 2)].map(code).filter((c) => c !== code(map));
  v5single(sub, 'Match the entries of List I with those of List II and choose the correct code.', code(map), wr.slice(0, 3), sol, trap, 'match', gid);
};
const v5passage = (gid, title, passage) => { V5GR[gid] = { title, passage }; };
const v5gen = (g) => V5G.push({ ...g, id: `${V5P}-v5g${V5G.length + 1}`, level: 5, exams: V5EX });
v5nat('heterogeneous equilibrium', '<p>Solid NH<sub>4</sub>HS decomposes as NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g). In a closed vessel at 298 K that held only the solid, the equilibrium total pressure is 1.20 atm. Extra NH<sub>3</sub> is now injected and the system settles again, with solid still present, at p(NH<sub>3</sub>) = 0.90 atm. The new total pressure in atm is</p>', 1.3, 0.01, 'atm',
  '<p>Idea: K<sub>p</sub> is fixed by temperature, so find it from the first state and use it for the second.</p><p>First state: the gases come out in equal amounts, so p(NH<sub>3</sub>) = p(H<sub>2</sub>S) = 1.20/2 = 0.60 atm and K<sub>p</sub> = 0.60 &times; 0.60 = 0.36 atm<sup>2</sup>.</p><p>Second state: p(H<sub>2</sub>S) = 0.36/0.90 = 0.40 atm (it falls, because the extra NH<sub>3</sub> pushes the equilibrium backward).</p><p>Total = 0.90 + 0.40 = <b>1.30 atm</b>.</p>',
  'After adding NH<sub>3</sub> the two gases are no longer equal, so &ldquo;total/2 each&rdquo; no longer works; use K<sub>p</sub> = p(NH<sub>3</sub>) &times; p(H<sub>2</sub>S).');
v5nat('approach to equilibrium', '<p>A &#8652; B is a one-step reversible first-order reaction with k<sub>f</sub> = 4.0 &times; 10<sup>-3</sup> s<sup>-1</sup> and k<sub>b</sub> = 1.0 &times; 10<sup>-3</sup> s<sup>-1</sup>. Starting with pure A, the time in seconds taken for the distance of [A] from its equilibrium value to fall to half of its initial value is (ln 2 = 0.693)</p>', 139, 2, 's',
  '<p>Idea: let x = [A] &minus; [A]<sub>eq</sub>. Then d[A]/dt = &minus;k<sub>f</sub>[A] + k<sub>b</sub>([A]<sub>0</sub> &minus; [A]); at equilibrium this is zero, so d x/dt = &minus;(k<sub>f</sub> + k<sub>b</sub>)x.</p><p>The distance from equilibrium decays as a first-order process with rate constant k<sub>f</sub> + k<sub>b</sub> = 5.0 &times; 10<sup>-3</sup> s<sup>-1</sup>.</p><p>t = 0.693 / (5.0 &times; 10<sup>-3</sup>) = <b>about 139 s</b>.</p>',
  'Using only k<sub>f</sub> gives 173 s. Both the forward and the backward steps pull the system towards equilibrium.');
v5nat('K<sub>p</sub> from molar mass', '<p>N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) is at equilibrium at a total pressure of 1.00 atm. The mean molar mass of the mixture is 69.0 g mol<sup>-1</sup> (M of N<sub>2</sub>O<sub>4</sub> = 92). K<sub>p</sub> in atm is</p>', 0.5, 0.01, 'atm',
  '<p>Idea: mean molar mass falls as the number of moles rises. Start with 1 mol N<sub>2</sub>O<sub>4</sub>: moles at equilibrium = 1 + &alpha;, mass is unchanged.</p><p>69.0 = 92/(1 + &alpha;), so 1 + &alpha; = 1.3333 and &alpha; = 0.3333.</p><p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 &minus; &alpha;<sup>2</sup>) = 4(1/9)(1.00)/(8/9) = <b>0.50 atm</b>.</p>',
  'Using &alpha; = 69/92 (or 23/69 with the wrong sign) is the usual slip; &alpha; comes from 92/M<sub>mean</sub> &minus; 1.');
v5nat('&Delta;G&deg; and K', '<p>The standard Gibbs energy of formation of NH<sub>3</sub>(g) at 298 K is &minus;17.12 kJ mol<sup>-1</sup>. For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) at 298 K, log<sub>10</sub>K<sub>p</sub> to the nearest integer is (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)</p>', 6, 0, '',
  '<p>Idea: &Delta;G&deg; belongs to the equation as written. Two moles of NH<sub>3</sub> form, so &Delta;G&deg; = 2 &times; (&minus;17.12) = &minus;34.24 kJ.</p><p>log K = 34240/(2.303 &times; 8.314 &times; 298) = 34240/5706 = 6.00, so the answer is <b>6</b>.</p>',
  'Using &minus;17.12 kJ (one mole of NH<sub>3</sub>) gives 3. Check that the equation you use has the same coefficients as the &Delta;G&deg;.');
v5nat('heterogeneous equilibrium', '<p>Excess graphite and 1.00 mol of CO<sub>2</sub> are sealed in a rigid 1.0 L vessel at 1000 K. C(s) + CO<sub>2</sub>(g) &#8652; 2CO(g) has K<sub>c</sub> = 2.0 mol L<sup>-1</sup>. Taking R = 0.08 L atm K<sup>-1</sup> mol<sup>-1</sup>, the total pressure at equilibrium in atm is</p>', 120, 0, 'atm',
  '<p>Idea: ICE for the gases only; graphite stays out of K<sub>c</sub>. If x mol of CO<sub>2</sub> reacts, CO formed = 2x.</p><p>K<sub>c</sub> = (2x)<sup>2</sup>/(1 &minus; x) = 2, so 4x<sup>2</sup> + 2x &minus; 2 = 0, i.e. 2x<sup>2</sup> + x &minus; 1 = 0, giving x = 0.50.</p><p>Gas moles = (1 &minus; 0.5) + 2(0.5) = 1.50 mol.</p><p>P = nRT/V = 1.50 &times; 0.08 &times; 1000 / 1.0 = <b>120 atm</b>.</p>',
  'Writing CO = x (not 2x) in the ICE table gives a wrong quadratic. Total moles also rise: the pressure is not that of the 1.00 mol you started with.');
v5msq('&Delta;G&deg;, &Delta;G and Q', '<p>For A(g) &#8652; B(g) at 298 K, &Delta;G&deg; = +5.71 kJ mol<sup>-1</sup> (take 2.303RT = 5.71 kJ mol<sup>-1</sup>; all pressures in bar). Which statements are correct?</p>',
  ['K = 0.10', 'Because &Delta;G&deg; is positive, no B is formed at all', 'In a mixture with Q = 0.010, &Delta;G = &minus;5.71 kJ mol<sup>-1</sup> and the net reaction goes forward', 'In a mixture with Q = 1, &Delta;G = +5.71 kJ mol<sup>-1</sup> and the net reaction goes backward', 'At equilibrium &Delta;G&deg; becomes zero'], [0, 2, 3],
  '<p>Idea: &Delta;G&deg; = &minus;RT ln K and &Delta;G = &Delta;G&deg; + RT ln Q = 2.303RT (log Q &minus; log K).</p><p>(A) log K = &minus;5.71/5.71 = &minus;1, so K = 0.10. Correct.</p><p>(B) False. &Delta;G&deg; &gt; 0 only means K &lt; 1: an equilibrium mixture still contains some B.</p><p>(C) &Delta;G = 5.71 + 5.71 log 0.010 = 5.71 &minus; 11.42 = &minus;5.71 kJ mol<sup>-1</sup>, negative, so forward. Correct.</p><p>(D) Q = 1 gives log Q = 0, &Delta;G = &Delta;G&deg; = +5.71 kJ mol<sup>-1</sup>, positive (Q &gt; K), so backward. Correct.</p><p>(E) False. &Delta;G&deg; is fixed by temperature; it is &Delta;G (not &Delta;G&deg;) that is zero at equilibrium.</p>',
  '&Delta;G&deg; &gt; 0 is not &ldquo;the reaction cannot happen&rdquo;; the sign of &Delta;G (that is, Q against K) decides the direction.');
v5msq('van&rsquo;t Hoff equation', '<p>A reaction has K = 10 at 300 K and K = 100 at 400 K. Assume &Delta;H&deg; and &Delta;S&deg; do not change with temperature (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>, ln 10 = 2.303). Which statements are correct?</p>',
  ['The reaction is endothermic', '&Delta;H&deg; is about +23 kJ mol<sup>-1</sup>', '&Delta;G&deg; at 300 K is about &minus;5.7 kJ mol<sup>-1</sup>', '&Delta;S&deg; is about +9.6 J K<sup>-1</sup> mol<sup>-1</sup>', 'K at 350 K is about 55'], [0, 1, 2],
  '<p>Idea: ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H&deg;/R)(1/T<sub>1</sub> &minus; 1/T<sub>2</sub>).</p><p>2.303 = (&Delta;H&deg;/8.314)(1/300 &minus; 1/400) = (&Delta;H&deg;/8.314)(8.333 &times; 10<sup>-4</sup>), so &Delta;H&deg; = +22.97 kJ mol<sup>-1</sup> (A, B correct; K rises with T, so endothermic).</p><p>&Delta;G&deg;(300) = &minus;RT ln 10 = &minus;8.314 &times; 300 &times; 2.303 = &minus;5.74 kJ mol<sup>-1</sup> (C correct).</p><p>&Delta;S&deg; = (&Delta;H&deg; &minus; &Delta;G&deg;)/T = (22.97 + 5.74)/300 = 0.0957 kJ K<sup>-1</sup> = +95.7 J K<sup>-1</sup> mol<sup>-1</sup>, not 9.6 (D false).</p><p>ln K(350) = 2.303 + 2763(1/300 &minus; 1/350) = 3.62, so K = 37, not 55 (E false: K does not change linearly with T).</p>',
  'The kilojoule to joule slip in &Delta;S&deg; (factor of 10 here) and averaging K between two temperatures are the usual traps.');
v5match('equilibrium constants', 'Reaction (i) A &#8652; B has K = 2 and reaction (ii) B &#8652; C has K = 3 at the same temperature. Match the new equilibrium with its constant',
  ['A &#8652; C', 'C &#8652; A', '2A &#8652; 2C', '2B &#8652; A + C'], ['6', '1/6', '36', '1.5', '0.5'], ['p', 'q', 'r', 's'],
  '<p>Idea: adding equations multiplies K; reversing takes 1/K; multiplying coefficients by n raises K to the power n.</p><p>A: (i) + (ii) gives K = 2 &times; 3 = 6 (p). B: the reverse of A, 1/6 (q). C: twice A, 6<sup>2</sup> = 36 (r).</p><p>D: 2B &#8652; A + C is (reverse of i, K = 1/2) + (ii, K = 3): K = 3/2 = 1.5 (s).</p>',
  'In D the reverse of (i) must be used, not (i) itself.');
v5match('&Delta;G&deg; and K', 'For N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) at 298 K, &Delta;G&deg; = +5.71 kJ mol<sup>-1</sup> for the equation as written (take 2.303RT = 5.71 kJ mol<sup>-1</sup>). Match the quantity with its value',
  ['&Delta;G&deg; of 2NO<sub>2</sub> &#8652; N<sub>2</sub>O<sub>4</sub>', '&Delta;G&deg; of &frac12;N<sub>2</sub>O<sub>4</sub> &#8652; NO<sub>2</sub>', '&Delta;G of the mixture at equilibrium', '&Delta;G (for the equation as written) of a mixture with Q = 1'],
  ['&minus;5.71 kJ mol<sup>-1</sup>', '+2.86 kJ mol<sup>-1</sup>', '0', '+5.71 kJ mol<sup>-1</sup>', '+11.42 kJ mol<sup>-1</sup>'], ['p', 'q', 'r', 's'],
  '<p>&Delta;G&deg; changes sign when the equation is reversed (A: &minus;5.71, p) and scales with the coefficients (B: half, +2.86, q).</p><p>C: at equilibrium &Delta;G = 0 (r), whatever &Delta;G&deg; is.</p><p>D: &Delta;G = &Delta;G&deg; + RT ln Q = &Delta;G&deg; + 0 = +5.71 kJ mol<sup>-1</sup> (s).</p>',
  '&Delta;G&deg; (all at standard states) and &Delta;G (the actual mixture) are different things; equilibrium makes &Delta;G, not &Delta;G&deg;, zero.');
v5passage('v5p1', 'Graphite and carbon dioxide', '<p>Excess graphite is kept with CO<sub>2</sub> in a closed vessel at 1000 K, and C(s) + CO<sub>2</sub>(g) &#8652; 2CO(g) reaches equilibrium. When the total pressure of the gas is 1.00 atm, the gas is 50% CO by volume. Treat all gases as ideal.</p>');
v5nat('K<sub>p</sub>', 'K<sub>p</sub> for the reaction, in atm, is', 0.5, 0.01, 'atm', '<p>At 1.00 atm: p(CO) = 0.50, p(CO<sub>2</sub>) = 0.50 atm. Graphite is left out.</p><p>K<sub>p</sub> = p(CO)<sup>2</sup>/p(CO<sub>2</sub>) = 0.25/0.50 = <b>0.50 atm</b>.</p>', 'Putting 1.00 in the numerator and denominator (using &ldquo;total pressure&rdquo;) is wrong; use the partial pressures.', 'passage', 'v5p1');
v5nat('K<sub>p</sub> and total pressure', 'The total pressure (atm) at which the gas phase is only 20% CO by volume is', 10, 0, 'atm', '<p>Let the total pressure be P. Then p(CO) = 0.20P, p(CO<sub>2</sub>) = 0.80P.</p><p>K<sub>p</sub> = (0.20P)<sup>2</sup>/(0.80P) = 0.05P = 0.50, so P = <b>10 atm</b>.</p><p>K<sub>p</sub> has pressure units here, so it grows with P in this form: more pressure favours CO<sub>2</sub> (fewer moles).</p>', 'Forgetting that one P in the numerator cancels against the denominator leaves P<sup>2</sup>, which gives a wrong answer.', 'passage', 'v5p1');
v5single('K<sub>p</sub> and total pressure', 'At the same temperature the total pressure is raised to 4.0 atm (graphite still present). The mole fraction of CO in the gas is about', 'about 0.30', ['0.50, because K<sub>p</sub> is unchanged', '0.25, because the pressure is doubled twice', '0.35'], '<p>Let p(CO) = x at P = 4.0: x<sup>2</sup>/(4.0 &minus; x) = 0.50, so x<sup>2</sup> + 0.5x &minus; 2.0 = 0, x = (&minus;0.5 + &radic;8.25)/2 = 1.186 atm.</p><p>Mole fraction = 1.186/4.0 = <b>0.30</b>. Higher pressure favours the side with fewer gas moles (CO<sub>2</sub>), so the CO fraction falls from 0.50, but K<sub>p</sub> is unchanged.</p>', 'K<sub>p</sub> unchanged does not mean the composition is unchanged: K<sub>p</sub> = x<sub>CO</sub><sup>2</sup>P/x<sub>CO2</sub> still contains one pressure factor.', 'passage', 'v5p1');
v5asr('Le Chatelier principle', 'When an equilibrium mixture of H<sub>2</sub>, I<sub>2</sub> and HI is compressed at constant temperature, the violet colour becomes deeper although the mole fractions of the three gases stay the same.', 'Compression raises the concentration of I<sub>2</sub> vapour, and because &Delta;n<sub>g</sub> = 0 the position of the equilibrium does not shift.', 0,
  '<p>Compressing to a smaller volume raises every concentration, including that of coloured I<sub>2</sub>, so the colour looks deeper. For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, Q = [HI]<sup>2</sup>/([H<sub>2</sub>][I<sub>2</sub>]) does not depend on the volume, so Q stays equal to K and there is no shift: the mole fractions do not change.</p><p>A is true, R is true and R explains A: <b>option 1</b>.</p>', 'The darker colour is a concentration effect, not a shift of equilibrium.');
v5fixed('mixed counting', '<p>How many of the following are correct?</p><p>(1) For a reaction with &Delta;n<sub>g</sub> = 0, K<sub>p</sub> = K<sub>c</sub> and both have no units.<br>(2) Doubling all the coefficients of a balanced equation squares K.<br>(3) A catalyst lowers the activation energy of the forward reaction only.<br>(4) For an endothermic reaction a graph of ln K against 1/T has a negative slope.<br>(5) At constant temperature, doubling the volume of an equilibrium mixture of 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> changes the number of moles of HI.</p>', ['1', '2', '3', '4'], 2,
  '<p>(1) True: (RT)<sup>0</sup> = 1 and the concentration units cancel. (2) True: K<sub>new</sub> = K<sup>2</sup>. (3) False: the catalyst lowers the barrier of both directions. (4) True: slope = &minus;&Delta;H&deg;/R is negative when &Delta;H&deg; &gt; 0. (5) False: &Delta;n<sub>g</sub> = 0, so volume changes do not shift the equilibrium.</p><p>Three are correct: <b>3</b>.</p>', 'Statement (5) tempts people to say &ldquo;lower pressure shifts it&rdquo;; it only does so when &Delta;n<sub>g</sub> is not zero.', 'statements');
v5single('degree of dissociation', 'A(g) &#8652; B(g) + 2C(g). The vapour density of undissociated A is d and that of the equilibrium mixture is D (same temperature and pressure basis). The degree of dissociation &alpha; is', '(d &minus; D)/(2D)', ['(d &minus; D)/D', '(d &minus; D)/(3D)', '(d &minus; D)/(2d)'],
  '<p>Idea: the mass is conserved, so the vapour density is inversely proportional to the number of moles.</p><p>1 mol A gives 1 + 2&alpha; mol of gas (1 &minus; &alpha; A, &alpha; B, 2&alpha; C). So D = d/(1 + 2&alpha;), 1 + 2&alpha; = d/D and &alpha; = <b>(d &minus; D)/(2D)</b>.</p>', 'The textbook formula (d &minus; D)/D is only for one extra mole (&Delta;n = 1); here each dissociated mole adds 2.');

v5gen({ type: 'nat', sub: 'K<sub>p</sub> and total pressure', make(rng) {
  const P = choose(rng, [1, 2, 3, 5]); const f = choose(rng, [0.3, 0.4, 0.5, 0.6, 0.7]); const x0 = f * P; const Kp = +(x0 * x0 / (P - x0)).toFixed(3);
  const x = (-Kp + Math.sqrt(Kp * Kp + 4 * Kp * P)) / 2;
  return { q: `Excess graphite is kept with CO<sub>2</sub> in a closed vessel. For C(s) + CO<sub>2</sub>(g) &#8652; 2CO(g), K<sub>p</sub> = ${Kp} atm at the working temperature. At a total gas pressure of ${P} atm, the partial pressure of CO in atm is`, answer: +x.toFixed(3), tol: 0.02, unit: 'atm', P, Kp,
    sol: `<p>Let p(CO) = x, so p(CO<sub>2</sub>) = ${P} &minus; x. K<sub>p</sub> = x<sup>2</sup>/(${P} &minus; x) = ${Kp}.</p><p>x<sup>2</sup> + ${Kp}x &minus; ${+(Kp * P).toFixed(3)} = 0, x = [&minus;${Kp} + &radic;(${Kp}<sup>2</sup> + 4 &times; ${+(Kp * P).toFixed(3)})]/2 = <b>${x.toFixed(3)} atm</b>.</p>` }; },
  verify: (p) => { let lo = 0, hi = p.P; for (let i = 0; i < 80; i++) { const m = (lo + hi) / 2; if (m * m / (p.P - m) < p.Kp) lo = m; else hi = m; } return (lo + hi) / 2; } });
v5gen({ type: 'nat', sub: 'approach to equilibrium', make(rng) {
  const kf = choose(rng, [2, 3, 4, 6, 8]) * 1e-3; const kb = choose(rng, [0.5, 1, 1.5, 2]) * 1e-3; const t = Math.LN2 / (kf + kb);
  return { q: `A &#8652; B is a one-step reversible first-order reaction with k<sub>f</sub> = ${kf * 1e3} &times; 10<sup>-3</sup> s<sup>-1</sup> and k<sub>b</sub> = ${kb * 1e3} &times; 10<sup>-3</sup> s<sup>-1</sup>. Starting from pure A, how long (s) does it take for the distance of [A] from its equilibrium value to halve? (ln 2 = 0.693)`, answer: +t.toFixed(1), tol: Math.max(1, +(0.012 * t).toFixed(1)), unit: 's', kf, kb,
    sol: `<p>The distance from equilibrium decays with rate constant k<sub>f</sub> + k<sub>b</sub> = ${+((kf + kb) * 1e3).toFixed(2)} &times; 10<sup>-3</sup> s<sup>-1</sup>.</p><p>t = 0.693/(k<sub>f</sub> + k<sub>b</sub>) = <b>${t.toFixed(1)} s</b>. (Using k<sub>f</sub> alone would be wrong.)</p>`, trap: 'Both rate constants set how fast equilibrium is approached.' }; },
  verify: (p) => { const xe = p.kb / (p.kf + p.kb); let a = 1, tm = 0; const dt = 0.01; while (a - xe > (1 - xe) / 2) { a += (-p.kf * a + p.kb * (1 - a)) * dt; tm += dt; } return tm; } });
v5gen({ type: 'nat', sub: 'K<sub>p</sub> from molar mass', make(rng) {
  const al0 = pick(rng, 0.1, 0.6, 0.05); const P = choose(rng, [0.5, 1, 2]); const M = +(92 / (1 + al0)).toFixed(1); const al = 92 / M - 1; const Kp = 4 * al * al * P / (1 - al * al);
  return { q: `N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) is at equilibrium at a total pressure of ${P} atm and the mean molar mass of the mixture is ${M} g mol<sup>-1</sup> (M of N<sub>2</sub>O<sub>4</sub> = 92). K<sub>p</sub> in atm is`, answer: +Kp.toFixed(3), tol: Math.max(0.005, +(0.02 * Kp).toFixed(3)), unit: 'atm', M, P,
    sol: `<p>Moles go from 1 to 1 + &alpha; with the mass unchanged, so ${M} = 92/(1 + &alpha;) and &alpha; = 92/${M} &minus; 1 = ${al.toFixed(4)}.</p><p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 &minus; &alpha;<sup>2</sup>) = <b>${Kp.toFixed(3)} atm</b>.</p>`, trap: '&alpha; = 92/M &minus; 1, not M/92.' }; },
  verify: (p) => { const a = 92 / p.M - 1; const tot = 1 + a; const pn = (2 * a / tot) * p.P, po = ((1 - a) / tot) * p.P; return pn * pn / po; } });


const V5BASE = {
  topic: 'chemical-equilibrium',
  groups: {
    ...XGR,
    m1: { title: 'N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), &Delta;H &lt; 0. Match the change with its effect', list1: ['A. Increase the total pressure by compression', 'B. Raise the temperature', 'C. Add a catalyst', 'D. Add argon at constant volume'], list2: ['p. Equilibrium shifts towards N<sub>2</sub> and H<sub>2</sub>', 'q. Equilibrium shifts towards NH<sub>3</sub>', 'r. Same composition, reached sooner', 's. No change in any concentration'] },
    m2: { title: 'Match the reaction with the unit of K<sub>c</sub>', list1: ['A. N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub>', 'B. N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>', 'C. H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI', 'D. 2SO<sub>2</sub> + O<sub>2</sub> &#8652; 2SO<sub>3</sub>'], list2: ['p. No unit', 'q. mol L<sup>-1</sup>', 'r. L mol<sup>-1</sup>', 's. L<sup>2</sup> mol<sup>-2</sup>'] },
    m3: { title: 'Match the condition with the direction of the net reaction', list1: ['A. Q &lt; K', 'B. Q &gt; K', 'C. Q = K', 'D. Products absent at the start'], list2: ['p. Net backward reaction', 'q. System at equilibrium', 'r. Net forward reaction, &Delta;G &lt; 0', 's. Only the forward reaction occurs at first'] },
    m4: { title: 'Match the equilibrium with the expression for K<sub>p</sub>', list1: ['A. CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g)', 'B. NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g)', 'C. 2NH<sub>3</sub>(g) &#8652; N<sub>2</sub>(g) + 3H<sub>2</sub>(g)', 'D. C(s) + CO<sub>2</sub>(g) &#8652; 2CO(g)'], list2: ['p. p(NH<sub>3</sub>) &times; p(H<sub>2</sub>S)', 'q. p(CO)<sup>2</sup> / p(CO<sub>2</sub>)', 'r. p(CO<sub>2</sub>)', 's. p(N<sub>2</sub>) p(H<sub>2</sub>)<sup>3</sup> / p(NH<sub>3</sub>)<sup>2</sup>'] },
    p1: { title: 'Dinitrogen tetroxide in a closed vessel', passage: '<p>Pure N<sub>2</sub>O<sub>4</sub>(g), colourless, is placed in a rigid vessel at 400 K at an initial pressure of <b>1.00 atm</b>. It partly dissociates: N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) (brown), &Delta;H = +57 kJ mol<sup>-1</sup>. At equilibrium the total pressure is <b>1.20 atm</b>.</p>' },
    p2: { title: 'The Haber process', passage: '<p>Ammonia is made by N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), &Delta;H = -92 kJ mol<sup>-1</sup>. In industry the gases are passed over iron at about 700 K and 200 atm; the ammonia is cooled to a liquid and removed, and unreacted gases are recycled.</p>' },
    p3: { title: 'Compressing an equilibrium mixture', passage: '<p>In a closed flask at constant temperature, PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is at equilibrium with [PCl<sub>5</sub>] = 0.40, [PCl<sub>3</sub>] = 0.20 and [Cl<sub>2</sub>] = 0.20 mol L<sup>-1</sup>. The volume is then suddenly halved and the mixture is allowed to reach a new equilibrium at the same temperature.</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    mk('ce-001', 1, 'dynamic equilibrium', 'At chemical equilibrium in a closed vessel,', 'the rates of the forward and backward reactions are equal', ['the forward and backward reactions have stopped', 'the concentrations of reactants and products are equal', 'the reaction is complete'], '<p>Equilibrium is <b>dynamic</b>: both reactions go on, at equal rates, so concentrations stay constant. They are constant, not necessarily equal.</p>'),
    mk('ce-002', 1, 'law of mass action', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), the expression for K<sub>c</sub> is', '[NH<sub>3</sub>]<sup>2</sup> / ([N<sub>2</sub>][H<sub>2</sub>]<sup>3</sup>)', ['[NH<sub>3</sub>] / ([N<sub>2</sub>][H<sub>2</sub>])', '[N<sub>2</sub>][H<sub>2</sub>]<sup>3</sup> / [NH<sub>3</sub>]<sup>2</sup>', '2[NH<sub>3</sub>] / ([N<sub>2</sub>] 3[H<sub>2</sub>])'], '<p>Products on top, reactants below, each raised to the power of its coefficient. Option B is K<sub>c</sub> for the reverse reaction.</p>'),
    mk('ce-003', 1, 'heterogeneous equilibrium', 'For CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g), K<sub>c</sub> is', '[CO<sub>2</sub>]', ['[CaO][CO<sub>2</sub>] / [CaCO<sub>3</sub>]', '[CaO] / [CaCO<sub>3</sub>]', '1 / [CO<sub>2</sub>]'], '<p>The concentration of a pure solid or liquid is constant and is taken as 1 in K, so only the gas appears: K<sub>c</sub> = [CO<sub>2</sub>] and K<sub>p</sub> = p(CO<sub>2</sub>).</p>'),
    mk('ce-004', 1, 'catalyst', 'A catalyst added to a reaction at equilibrium', 'speeds up both forward and backward reactions equally and does not change K', ['increases K', 'shifts the equilibrium towards products', 'decreases the activation energy of the forward reaction only'], '<p>A catalyst lowers the activation energy of both directions by the same amount, so equilibrium is reached sooner but its position and K are unchanged.</p>'),
    mk('ce-005', 1, 'K and temperature', 'The value of the equilibrium constant of a reaction depends on', 'temperature only', ['pressure only', 'initial concentrations', 'the presence of a catalyst'], '<p>For a given reaction K changes only with temperature. Concentration, pressure, volume or a catalyst may change the composition or the speed but not K.</p>'),
    mk('ce-006', 1, 'reaction quotient', 'If the reaction quotient Q is greater than K, the reaction proceeds', 'in the backward direction', ['in the forward direction', 'with no change', 'only if a catalyst is added'], '<p>Q &gt; K means there are too many products compared with equilibrium, so products are used up and the net reaction goes backward until Q = K.</p>'),
    mk('ce-007', 1, 'K<sub>p</sub> and K<sub>c</sub>', 'For which reaction is K<sub>p</sub> equal to K<sub>c</sub>?', 'H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', 'PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', '2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)'], '<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>. They are equal only if &Delta;n<sub>g</sub> = 0. Only H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI has 2 mol of gas on each side.</p>'),
    mk('ce-008', 1, 'Le Chatelier principle', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), increasing the pressure by reducing the volume', 'shifts the equilibrium to the right', ['shifts the equilibrium to the left', 'does not shift the equilibrium', 'changes the value of K'], '<p>The system opposes a rise in pressure by reducing the number of gas moles: 4 mol on the left, 2 mol on the right. So the equilibrium moves right (more NH<sub>3</sub>). K is unchanged.</p>'),
    mk('ce-009', 1, 'Le Chatelier principle', 'On heating, the equilibrium of an endothermic reaction', 'shifts towards the products', ['shifts towards the reactants', 'does not change', 'is destroyed'], '<p>Heat is like a reactant for an endothermic reaction. Adding heat favours the forward direction, which absorbs it, and K increases.</p>'),
    mk('ce-010', 1, 'units of K', 'The unit of K<sub>c</sub> for N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) is', 'mol L<sup>-1</sup>', ['mol<sup>-1</sup> L', 'it has no unit', 'mol<sup>2</sup> L<sup>-2</sup>'], '<p>K<sub>c</sub> = [NO<sub>2</sub>]<sup>2</sup>/[N<sub>2</sub>O<sub>4</sub>] has units (mol L<sup>-1</sup>)<sup>2-1</sup> = mol L<sup>-1</sup>. The unit is (mol L<sup>-1</sup>)<sup>&Delta;n</sup>.</p>'),
    mk('ce-011', 1, 'meaning of K', 'A very large value of K (for example 10<sup>10</sup>) means that at equilibrium', 'products are strongly favoured', ['reactants are strongly favoured', 'the reaction is very fast', 'the reaction has stopped'], '<p>K is products over reactants, so a big K means mostly products. It says nothing about speed (that is rate and activation energy).</p>', 'K tells where the equilibrium lies, not how fast it is reached.'),
    mk('ce-012', 1, 'dynamic equilibrium', 'Which statement about the equilibrium H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI in a closed vessel is <b>not</b> correct?', '[H<sub>2</sub>] must equal [HI]', ['The colour of the mixture stays constant', 'The same equilibrium can be reached starting from pure HI', 'The forward and backward rates are equal'], '<p>Equilibrium needs constant concentrations, not equal ones. Starting from H<sub>2</sub> and I<sub>2</sub> or from HI alone gives the same equilibrium mixture at the same temperature.</p>'),

    // ---------- Level 2 ----------
    nat('ce-013', 2, 'calculating K<sub>c</sub>', 'At equilibrium for H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g): [H<sub>2</sub>] = 0.10, [I<sub>2</sub>] = 0.10 and [HI] = 0.80 mol L<sup>-1</sup>. Find K<sub>c</sub>.', 64, 0, '', '<p>K<sub>c</sub> = [HI]<sup>2</sup>/([H<sub>2</sub>][I<sub>2</sub>]) = 0.64 / (0.10 &times; 0.10) = <b>64</b>. No unit since &Delta;n = 0.</p>', 'Forgetting to square [HI] gives 80.'),
    nat('ce-014', 2, 'reversing an equation', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>c</sub> = 64 at a certain temperature. Find K<sub>c</sub> for 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> at the same temperature.', 0.0156, 0.0005, '', '<p>Reversing a reaction inverts K: K&prime; = 1/64 = <b>0.0156</b>.</p>'),
    mk('ce-015', 2, 'changing the equation', 'For N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> the constant is K. For &frac12;N<sub>2</sub> + 3/2 H<sub>2</sub> &#8652; NH<sub>3</sub> at the same temperature it is', '&radic;K', ['K/2', '2K', 'K<sup>2</sup>'], '<p>Multiplying all coefficients by n raises K to the power n. Here n = 1/2, so K&prime; = K<sup>1/2</sup>.</p>'),
    nat('ce-016', 2, 'K<sub>p</sub> and K<sub>c</sub>', 'For N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g), K<sub>c</sub> = 0.040 mol L<sup>-1</sup> at 400 K. Find K<sub>p</sub> in atm. (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)', 1.31, 0.02, 'atm', '<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>, with &Delta;n<sub>g</sub> = 2 - 1 = 1.</p><p>K<sub>p</sub> = 0.040 &times; 0.0821 &times; 400 = <b>1.31 atm</b>.</p>'),
    mk('ce-017', 2, 'reaction quotient', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>c</sub> = 50. A mixture has [H<sub>2</sub>] = [I<sub>2</sub>] = 0.20 and [HI] = 1.2 mol L<sup>-1</sup>. The mixture', 'is not at equilibrium and moves forward', ['is not at equilibrium and moves backward', 'is at equilibrium', 'has Q = 6'], '<p>Q = (1.2)<sup>2</sup>/(0.20 &times; 0.20) = 1.44/0.04 = 36. Since Q (36) &lt; K (50), more HI must form: the net reaction goes forward.</p>'),
    nat('ce-018', 2, 'degree of dissociation', 'PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is 40% dissociated at a total pressure of 2.1 atm. Find K<sub>p</sub> in atm.', 0.40, 0.01, 'atm', '<p>Start with 1 mol PCl<sub>5</sub>. At equilibrium: PCl<sub>5</sub> 0.6, PCl<sub>3</sub> 0.4, Cl<sub>2</sub> 0.4; total 1.4 mol.</p><p>Partial pressures: 0.6/1.4 &times; 2.1 = 0.9; 0.4/1.4 &times; 2.1 = 0.6 each.</p><p>K<sub>p</sub> = (0.6 &times; 0.6)/0.9 = <b>0.40 atm</b>. (Formula: &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 0.16 &times; 2.1/0.84.)</p>'),
    nat('ce-019', 2, 'vapour density', 'The theoretical vapour density of PCl<sub>5</sub> is 104.25. At a certain temperature the observed vapour density of its equilibrium mixture is 80.19. Find the degree of dissociation.', 0.30, 0.01, '', '<p>For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>, one mole gives 1 + &alpha; moles, so the density falls: D/d = 1 + &alpha;.</p><p>&alpha; = (D - d)/d = (104.25 - 80.19)/80.19 = <b>0.30</b>.</p>', 'Dividing by D instead of d gives 0.23.'),
    mk('ce-020', 2, 'heterogeneous equilibrium', 'CaCO<sub>3</sub>(s) is in equilibrium with CaO(s) and CO<sub>2</sub>(g) in a closed vessel at constant temperature. If more CaCO<sub>3</sub>(s) is added, the pressure of CO<sub>2</sub>', 'does not change', ['increases', 'decreases', 'first falls and then rises'], '<p>K<sub>p</sub> = p(CO<sub>2</sub>), and K<sub>p</sub> depends only on temperature. Pure solids do not appear in K, so adding more solid does not shift the equilibrium. p(CO<sub>2</sub>) stays the same.</p>', 'The famous misconception: adding any reactant shifts the equilibrium; not a solid.'),
    mk('ce-021', 2, 'Le Chatelier principle', 'In N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) at equilibrium, extra H<sub>2</sub> is added at constant volume and temperature. Afterwards', 'more NH<sub>3</sub> is formed and K is unchanged', ['more NH<sub>3</sub> is formed and K increases', 'NH<sub>3</sub> decreases and K decreases', 'nothing changes, as the system is at equilibrium'], '<p>Adding H<sub>2</sub> makes Q &lt; K, so the net reaction moves forward until Q = K again. K itself depends only on temperature.</p>'),
    mk('ce-022', 2, 'effect of volume', 'For PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g), when the volume of the vessel is reduced at constant temperature, the degree of dissociation', 'decreases', ['increases', 'stays the same', 'becomes zero'], '<p>Less volume means higher pressure. The system moves to the side with fewer gas moles: 1 mol (PCl<sub>5</sub>) against 2 mol. So the equilibrium shifts back and &alpha; falls.</p>'),
    nat('ce-023', 2, 'ICE table', '0.20 mol L<sup>-1</sup> N<sub>2</sub>O<sub>4</sub> is placed in a vessel. At equilibrium [NO<sub>2</sub>] = 0.080 mol L<sup>-1</sup>. Find K<sub>c</sub> for N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> in mol L<sup>-1</sup>.', 0.040, 0.001, 'mol L<sup>-1</sup>', '<p>[NO<sub>2</sub>] = 2x = 0.080, so x = 0.040. [N<sub>2</sub>O<sub>4</sub>] = 0.20 - 0.040 = 0.16.</p><p>K<sub>c</sub> = (0.080)<sup>2</sup>/0.16 = 0.0064/0.16 = <b>0.040</b>.</p>', 'Using 0.080 as the amount of N<sub>2</sub>O<sub>4</sub> that reacted.'),
    nat('ce-024', 2, 'ICE table', 'One mole each of H<sub>2</sub> and I<sub>2</sub> are heated in a 1 L vessel. K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI is 4.0 at that temperature. Find the amount of HI (mol) at equilibrium.', 1.0, 0.02, 'mol', '<p>Let x mol of each react: [HI] = 2x, [H<sub>2</sub>] = [I<sub>2</sub>] = 1 - x.</p><p>(2x)<sup>2</sup>/(1 - x)<sup>2</sup> = 4, so 2x/(1 - x) = 2 and x = 0.5. HI = 2x = <b>1.0 mol</b>.</p>'),
    mk('ce-025', 2, 'Haber process', 'The formation of NH<sub>3</sub> is exothermic. A moderate temperature (about 700 K) is used in industry because', 'low temperature favours yield but makes the reaction too slow', ['high temperature increases K', 'a catalyst works only at high temperature', 'NH<sub>3</sub> is decomposed at 300 K'], '<p>A compromise: lowering temperature raises K and the yield, but the rate becomes too slow. About 700 K with an iron catalyst gives a fair rate and acceptable yield.</p>'),
    mk('ce-026', 2, 'units of K<sub>p</sub>', 'The unit of K<sub>p</sub> for N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), pressures in atm, is', 'atm<sup>-2</sup>', ['atm<sup>2</sup>', 'atm', 'no unit'], '<p>K<sub>p</sub> = p(NH<sub>3</sub>)<sup>2</sup>/(p(N<sub>2</sub>)p(H<sub>2</sub>)<sup>3</sup>) has units atm<sup>2-4</sup> = atm<sup>-2</sup>.</p>'),
    nat('ce-027', 2, 'heterogeneous equilibrium', 'Solid NH<sub>4</sub>HS decomposes: NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g). At equilibrium in a vessel the total pressure is 0.80 atm. Find K<sub>p</sub> in atm<sup>2</sup>.', 0.16, 0.005, 'atm<sup>2</sup>', '<p>NH<sub>3</sub> and H<sub>2</sub>S are formed in equal amounts, so each has a partial pressure of 0.40 atm.</p><p>K<sub>p</sub> = 0.40 &times; 0.40 = <b>0.16 atm<sup>2</sup></b>.</p>', 'Using 0.80 for each gas gives 0.64.'),
    nat('ce-028', 2, 'heterogeneous equilibrium', 'Ammonium carbamate decomposes: NH<sub>2</sub>COONH<sub>4</sub>(s) &#8652; 2NH<sub>3</sub>(g) + CO<sub>2</sub>(g). At equilibrium the total pressure is 0.90 atm. Find K<sub>p</sub> in atm<sup>3</sup>.', 0.108, 0.002, 'atm<sup>3</sup>', '<p>The gases are in the ratio 2 : 1, so p(NH<sub>3</sub>) = 2/3 &times; 0.90 = 0.60 atm and p(CO<sub>2</sub>) = 0.30 atm.</p><p>K<sub>p</sub> = (0.60)<sup>2</sup>(0.30) = <b>0.108 atm<sup>3</sup></b>.</p>'),
    nat('ce-029', 2, 'combining equilibria', 'A &#8652; B has K = 4 and B &#8652; C has K = 5 at the same temperature. Find K for A &#8652; C.', 20, 0, '', '<p>Adding two reactions multiplies their constants: K = 4 &times; 5 = <b>20</b>.</p>'),
    asr('ce-030', 2, 'catalyst', 'A catalyst does not change the equilibrium constant of a reaction.', 'A catalyst lowers the activation energy of the forward and the backward reactions equally.', 0, '<p>Both are true. If both rate constants rise by the same factor, their ratio K = k<sub>f</sub>/k<sub>b</sub> is unchanged. R explains A.</p>'),
    asr('ce-031', 2, 'effect of pressure', 'Increasing the pressure on PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> at equilibrium decreases the amount of PCl<sub>3</sub>.', 'The backward reaction produces fewer moles of gas than the forward reaction.', 0, '<p>Both are true. Higher pressure favours the side with fewer moles of gas (PCl<sub>5</sub>, 1 mol against 2 mol), so PCl<sub>3</sub> falls. R is the reason.</p>'),
    stm('ce-032', 2, 'K<sub>c</sub> and units', 'K<sub>c</sub> of H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI has no unit.', 'For this reaction K<sub>p</sub> = K<sub>c</sub>.', 0, '<p>&Delta;n<sub>g</sub> = 0, so units cancel and (RT)<sup>0</sup> = 1. Both correct.</p>'),

    // ---------- Level 3 ----------
    nat('ce-033', 3, 'degree of dissociation', 'PCl<sub>5</sub> is 50% dissociated at 1.0 atm total pressure. Find K<sub>p</sub> in atm.', 0.333, 0.005, 'atm', '<p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = (0.25)(1.0)/(0.75) = <b>0.333 atm</b>.</p>'),
    nat('ce-034', 3, 'degree of dissociation', 'N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> is 20% dissociated at 1.0 atm total pressure. Find K<sub>p</sub> in atm.', 0.167, 0.003, 'atm', '<p>One mole N<sub>2</sub>O<sub>4</sub> gives 1 - &alpha; and 2&alpha; moles, total 1 + &alpha;.</p><p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 4(0.04)(1)/(0.96) = <b>0.167 atm</b>.</p>', 'The factor 4 comes from the 2NO<sub>2</sub> squared.'),
    nat('ce-035', 3, 'degree of dissociation', 'With K<sub>p</sub> = 0.1667 atm for N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, find the degree of dissociation at a total pressure of 4.0 atm.', 0.10, 0.005, '', '<p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>). So &alpha;<sup>2</sup>/(1 - &alpha;<sup>2</sup>) = 0.1667/16 = 0.01042, giving &alpha;<sup>2</sup> = 0.0103 and &alpha; = <b>0.10</b>.</p><p>At 1 atm it was 0.20: four times the pressure halves &alpha; (&alpha; &prop; P<sup>-1/2</sup> when &alpha; is small).</p>'),
    nat('ce-036', 3, 'vapour density', 'N<sub>2</sub>O<sub>4</sub> (M = 92) partly dissociates into NO<sub>2</sub>. The average molar mass of the equilibrium mixture is 76.7 g mol<sup>-1</sup>. Find the degree of dissociation.', 0.20, 0.01, '', '<p>Moles after dissociation = 1 + &alpha; for each mole. Since mass is conserved, M<sub>mix</sub> = M/(1 + &alpha;).</p><p>1 + &alpha; = 92/76.7 = 1.20, so &alpha; = <b>0.20</b>.</p>', 'Mixed with the mole concept.'),
    nat('ce-037', 3, 'van&rsquo;t Hoff equation', 'For an endothermic reaction &Delta;H = +50 kJ mol<sup>-1</sup>. By what factor does K increase when the temperature rises from 300 K to 310 K? (R = 8.314; assume &Delta;H is constant)', 1.91, 0.03, '', '<p>ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (50 000/8.314)(1/300 - 1/310) = 6014 &times; 1.075 &times; 10<sup>-4</sup> = 0.647.</p><p>K<sub>2</sub>/K<sub>1</sub> = e<sup>0.647</sup> = <b>1.91</b>.</p>'),
    nat('ce-038', 3, 'van&rsquo;t Hoff equation', 'For a reaction, K = 200 at 300 K and K = 3.63 at 400 K. Find &Delta;H in kJ mol<sup>-1</sup>. (R = 8.314)', -40, 0.6, 'kJ mol<sup>-1</sup>', '<p>ln(K<sub>2</sub>/K<sub>1</sub>) = ln(3.63/200) = -4.009. (1/T<sub>1</sub> - 1/T<sub>2</sub>) = 1/300 - 1/400 = 8.33 &times; 10<sup>-4</sup>.</p><p>&Delta;H = R &times; ln(K<sub>2</sub>/K<sub>1</sub>)/(1/T<sub>1</sub> - 1/T<sub>2</sub>) = 8.314 &times; (-4.009)/(8.33 &times; 10<sup>-4</sup>) = -40 000 J = <b>-40 kJ mol<sup>-1</sup></b>. K falls on heating, so the reaction is exothermic.</p>'),
    nat('ce-039', 3, 'mixed: thermodynamics', 'At 300 K the equilibrium constant of a reaction is 0.10. Find &Delta;G&deg; in kJ mol<sup>-1</sup>. (R = 8.314; log 0.1 = -1)', 5.74, 0.05, 'kJ mol<sup>-1</sup>', '<p>&Delta;G&deg; = -2.303RT log K = -2.303 &times; 8.314 &times; 300 &times; (-1) = +5743 J = <b>+5.74 kJ mol<sup>-1</sup></b>.</p><p>K &lt; 1 gives positive &Delta;G&deg;.</p>', 'Mixed with chemical thermodynamics.'),
    nat('ce-040', 3, 'mixed: thermodynamics', 'The standard Gibbs energy change of a reaction at 298 K is -17.1 kJ mol<sup>-1</sup>. Find log<sub>10</sub> K. (2.303RT = 5.71 kJ mol<sup>-1</sup> at 298 K)', 3.0, 0.02, '', '<p>&Delta;G&deg; = -2.303RT log K, so log K = 17.1/5.71 = <b>3.0</b> and K &asymp; 10<sup>3</sup>.</p>', 'Mixed with chemical thermodynamics.'),
    nat('ce-041', 3, 'heterogeneous equilibrium', 'CuSO<sub>4</sub>&middot;5H<sub>2</sub>O(s) &#8652; CuSO<sub>4</sub>&middot;3H<sub>2</sub>O(s) + 2H<sub>2</sub>O(g). At equilibrium the vapour pressure of water is 0.010 atm. Find K<sub>p</sub> in units of 10<sup>-4</sup> atm<sup>2</sup>.', 1.0, 0.02, '10<sup>-4</sup> atm<sup>2</sup>', '<p>Only the gas appears: K<sub>p</sub> = p(H<sub>2</sub>O)<sup>2</sup> = (0.010)<sup>2</sup> = 1.0 &times; 10<sup>-4</sup> atm<sup>2</sup>. Answer <b>1.0</b>.</p>', 'The power is the coefficient 2.'),
    nat('ce-042', 3, 'ICE table', 'A(g) &#8652; B(g) + C(g) has K<sub>c</sub> = 0.50 mol L<sup>-1</sup>. Start with 1.0 mol L<sup>-1</sup> of A. Find [B] at equilibrium in mol L<sup>-1</sup>.', 0.50, 0.01, 'mol L<sup>-1</sup>', '<p>x<sup>2</sup>/(1 - x) = 0.50, so x<sup>2</sup> + 0.5x - 0.5 = 0. x = [-0.5 + &radic;(0.25 + 2)]/2 = (-0.5 + 1.5)/2 = <b>0.50</b>.</p>'),
    nat('ce-043', 3, 'ICE table', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>c</sub> = 49. Decomposition of pure HI gives the same equilibrium. What fraction of HI decomposes? (2HI &#8652; H<sub>2</sub> + I<sub>2</sub>)', 0.222, 0.005, '', '<p>For 2HI &#8652; H<sub>2</sub> + I<sub>2</sub>, K&prime; = 1/49. Start with 1 mol HI; &alpha; decomposes: H<sub>2</sub> = I<sub>2</sub> = &alpha;/2, HI = 1 - &alpha;.</p><p>(&alpha;/2)<sup>2</sup>/(1 - &alpha;)<sup>2</sup> = 1/49, so (&alpha;/2)/(1 - &alpha;) = 1/7 and 7&alpha; = 2 - 2&alpha;. &alpha; = 2/9 = <b>0.222</b>.</p>'),
    nat('ce-044', 3, 'ICE table', 'A(g) + B(g) &#8652; C(g) + D(g), K<sub>c</sub> = 4. One mole each of A and B are placed in a 1 L vessel. Find the moles of C at equilibrium.', 0.667, 0.01, 'mol', '<p>x<sup>2</sup>/(1 - x)<sup>2</sup> = 4 so x/(1 - x) = 2 and x = <b>2/3 = 0.667 mol</b>.</p>'),
    mk('ce-045', 3, 'inert gas', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) at equilibrium, argon is added at <b>constant pressure</b>. The yield of NH<sub>3</sub>', 'decreases', ['increases', 'does not change', 'becomes zero'], '<p>At constant pressure the volume grows, so the partial pressures of all gases fall, like lowering the total pressure. The system shifts to the side with more gas moles (reactants: 4 mol against 2). NH<sub>3</sub> decreases.</p>', 'At constant volume, no shift. At constant pressure, argon acts like a lower pressure.'),
    mk('ce-046', 3, 'inert gas', 'For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> in a rigid vessel, helium is added. The degree of dissociation', 'stays the same, since the partial pressures are unchanged', ['increases, since total pressure increases', 'decreases, since total pressure increases', 'increases, since volume of gas increases'], '<p>Volume is fixed and He does not react, so each gas keeps its own moles per litre and partial pressure. Q is still equal to K, so nothing shifts.</p>', 'Total pressure rises, but the equilibrium depends on the partial pressures of the reacting gases.'),
    mk('ce-047', 3, 'temperature effect', 'For an exothermic reaction, a rise in temperature', 'decreases K and shifts the equilibrium backward', ['increases K and shifts it forward', 'does not change K but shifts it backward', 'increases the rate only of the backward reaction'], '<p>Heat is a product of an exothermic reaction; adding heat pushes the equilibrium back, so K falls. The rates of <i>both</i> reactions increase (the backward one more), so option C is also wrong.</p>'),
    mk('ce-048', 3, 'effect of removing a product', 'In the reaction CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g), the decomposition can be made complete by', 'heating in an open vessel so CO<sub>2</sub> escapes', ['heating in a closed vessel', 'increasing the pressure of CO<sub>2</sub>', 'adding more CaO'], '<p>Removing CO<sub>2</sub> keeps Q below K, so the reaction goes on to completion (limestone kilns work this way). In a closed vessel p(CO<sub>2</sub>) reaches K<sub>p</sub> and the reaction stops.</p>'),
    nat('ce-049', 3, 'mixed: mole concept', 'CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g) has K<sub>p</sub> = 0.821 atm at 1000 K. What is the minimum mass of CaCO<sub>3</sub> (g) that must be placed in a 10 L vessel (initially empty) at 1000 K for equilibrium to be established? (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>; CaCO<sub>3</sub> = 100 g mol<sup>-1</sup>)', 10, 0.2, 'g', '<p>At equilibrium p(CO<sub>2</sub>) = K<sub>p</sub> = 0.821 atm. Moles of CO<sub>2</sub> needed: n = PV/RT = 0.821 &times; 10/(0.0821 &times; 1000) = 0.100 mol.</p><p>Each mole of CO<sub>2</sub> comes from one mole of CaCO<sub>3</sub>: 0.100 mol &times; 100 g mol<sup>-1</sup> = <b>10 g</b>. Any less and all the solid decomposes before p reaches 0.821 atm.</p>', 'Mixed with the gas laws and the mole concept.'),
    asr('ce-050', 3, 'K<sub>p</sub> and K<sub>c</sub>', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>p</sub> equals K<sub>c</sub>.', 'The total pressure does not affect the position of equilibrium of this reaction.', 1, '<p>Both are true, but R is not the reason for A. K<sub>p</sub> = K<sub>c</sub> because &Delta;n<sub>g</sub> = 0. R is true for the same cause (equal moles of gas on both sides); one fact does not explain the other.</p>'),
    asr('ce-051', 3, 'K and pressure', 'The equilibrium constant of N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> increases when the pressure is increased.', 'By Le Chatelier&rsquo;s principle, an increase in pressure favours the formation of NH<sub>3</sub>.', 3, '<p>A is false: K depends only on temperature. R is true: the position of equilibrium shifts to the side with fewer moles, but K stays the same because Q recovers to the same K.</p>', 'Position of equilibrium vs value of K.'),
    stm('ce-052', 3, 'effect of temperature', 'The K of an endothermic reaction increases with temperature.', 'Increasing pressure always increases K for a gas-phase reaction.', 1, '<p>I is correct (van&rsquo;t Hoff). II is incorrect: K does not depend on pressure.</p>'),
    stm('ce-053', 3, 'catalyst', 'A catalyst increases the equilibrium yield of products.', 'A catalyst helps the equilibrium to be reached faster.', 2, '<p>I is false: K and the equilibrium composition are not changed by a catalyst. II is true: both rates rise, so equilibrium is reached sooner.</p>'),
    msq('ce-054', 3, 'Le Chatelier principle', 'For N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> (&Delta;H &lt; 0), which changes shift the equilibrium towards NH<sub>3</sub>?', ['Increasing the pressure by reducing the volume', 'Removing NH<sub>3</sub> as it forms', 'Adding a catalyst', 'Lowering the temperature'], [0, 1, 3], '<p>A: fewer gas moles on the right. B: Q falls below K. D: exothermic reaction favoured by cold. A catalyst changes only the rate.</p>'),
    msq('ce-055', 3, 'equilibrium constant', 'Which of the following do <b>not</b> change the value of K<sub>c</sub> of a reaction?', ['Temperature', 'Pressure', 'A catalyst', 'Initial concentrations'], [1, 2, 3], '<p>K<sub>c</sub> changes only with temperature. Pressure, catalyst and starting concentrations leave it alone.</p>'),
    mat('ce-056', 3, 'Le Chatelier principle', 'm1', 'Match List I with List II. Choose the correct code.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], '<p>A: compressing shifts the equilibrium towards the side with fewer moles, NH<sub>3</sub> (q). B: heating favours the endothermic backward direction (p). C: a catalyst gives the same composition sooner (r). D: argon at constant volume leaves all partial pressures unchanged (s).</p>'),
    mat('ce-057', 3, 'units of K', 'm2', 'Match List I with List II. Choose the correct code.', 'A-s, B-q, C-p, D-r', ['A-q, B-s, C-p, D-r', 'A-s, B-q, C-r, D-p', 'A-p, B-q, C-s, D-r'], '<p>Unit = (mol L<sup>-1</sup>)<sup>&Delta;n</sup>. A: &Delta;n = -2, L<sup>2</sup> mol<sup>-2</sup>. B: &Delta;n = +1, mol L<sup>-1</sup>. C: &Delta;n = 0, none. D: &Delta;n = -1, L mol<sup>-1</sup>.</p>'),
    mat('ce-058', 3, 'reaction quotient', 'm3', 'Match List I with List II. Choose the correct code.', 'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-p, C-s, D-q', 'A-q, B-p, C-r, D-s'], '<p>Q &lt; K: forward (r). Q &gt; K: backward (p). Q = K: equilibrium (q). With no products at the start, Q = 0, so only the forward reaction can go (s).</p>'),
    mat('ce-059', 3, 'K<sub>p</sub> expressions', 'm4', 'Match List I with List II. Choose the correct code.', 'A-r, B-p, C-s, D-q', ['A-p, B-r, C-s, D-q', 'A-r, B-p, C-q, D-s', 'A-s, B-p, C-r, D-q'], '<p>Solids are left out. A: only CO<sub>2</sub> (r). B: NH<sub>3</sub> &times; H<sub>2</sub>S (p). C: products over reactants squared (s). D: C(s) omitted: p(CO)<sup>2</sup>/p(CO<sub>2</sub>) (q).</p>'),

    // ---------- Level 4 ----------
    PN('ce-060', 4, 'degree of dissociation', 'p1', 'Find the degree of dissociation of N<sub>2</sub>O<sub>4</sub>.', 0.20, 0.01, '', '<p>At constant volume and temperature, pressure is proportional to moles. N<sub>2</sub>O<sub>4</sub>: 1.00 - p; NO<sub>2</sub>: 2p. Total = 1.00 + p = 1.20, so p = 0.20 atm.</p><p>&alpha; = 0.20/1.00 = <b>0.20</b>.</p>'),
    PN('ce-061', 4, 'K<sub>p</sub>', 'p1', 'Find K<sub>p</sub> in atm.', 0.20, 0.005, 'atm', '<p>p(N<sub>2</sub>O<sub>4</sub>) = 1.00 - 0.20 = 0.80 atm; p(NO<sub>2</sub>) = 0.40 atm.</p><p>K<sub>p</sub> = (0.40)<sup>2</sup>/0.80 = <b>0.20 atm</b>.</p>', 'Do not use the formula 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) with the initial pressure in place of the total pressure at equilibrium.'),
    P('ce-062', 4, 'Le Chatelier principle', 'p1', 'The vessel is cooled to 300 K. The brown colour of the gas', 'fades, because the endothermic forward reaction is disfavoured at lower temperature', ['deepens, because cooling raises K', 'stays the same, since the volume is fixed', 'fades, because cooling shifts the reaction to the side with more gas moles'], '<p>The forward reaction (making brown NO<sub>2</sub>) is endothermic. Cooling favours the exothermic reverse, giving colourless N<sub>2</sub>O<sub>4</sub>. K decreases on cooling.</p>'),
    P('ce-063', 4, 'Haber process', 'p2', 'A pressure as high as 200 atm is used because', 'there are fewer gas moles on the product side, so pressure raises the yield', ['it increases the value of K', 'it lowers the activation energy', 'it makes the reaction exothermic'], '<p>4 mol of gas become 2 mol, so by Le Chatelier a higher pressure favours NH<sub>3</sub>. K itself is unchanged by pressure, and a catalyst, not pressure, lowers the activation energy.</p>'),
    P('ce-064', 4, 'Haber process', 'p2', 'Cooling the mixture to liquefy NH<sub>3</sub> and removing it', 'keeps Q below K so the reaction keeps going forward', ['raises K', 'lowers the pressure and so lowers the yield', 'acts as a catalyst'], '<p>NH<sub>3</sub> liquefies at a far higher temperature than N<sub>2</sub> and H<sub>2</sub>. Removing it lowers its concentration, so Q &lt; K and more NH<sub>3</sub> is made.</p>'),
    P('ce-065', 4, 'Haber process', 'p2', 'Compared with the same reaction run at 500 K, the value of K at 700 K is', 'smaller, because the forward reaction is exothermic', ['larger, because the rate is faster', 'the same, since the catalyst is present', 'larger, because the pressure is higher'], '<p>For an exothermic reaction, K falls as temperature rises. The rate is higher at 700 K, but that is a rate effect, not an equilibrium effect.</p>'),
    P('ce-066', 4, 'reaction quotient', 'p3', 'Just after the volume is halved, the reaction quotient Q (in mol L<sup>-1</sup>) and the direction of change are', '0.20, backward', ['0.10, no change', '0.20, forward', '0.05, forward'], '<p>K<sub>c</sub> = (0.20)(0.20)/0.40 = 0.10. After halving the volume all concentrations double: 0.80, 0.40, 0.40.</p><p>Q = (0.40)(0.40)/0.80 = 0.20 &gt; K, so the net reaction is <b>backward</b>.</p>'),
    PN('ce-067', 4, 'ICE table', 'p3', 'Find the new equilibrium concentration of PCl<sub>3</sub> in mol L<sup>-1</sup>.', 0.30, 0.01, 'mol L<sup>-1</sup>', '<p>Start from the doubled values: PCl<sub>5</sub> 0.80, PCl<sub>3</sub> 0.40, Cl<sub>2</sub> 0.40. Let x of PCl<sub>3</sub> and Cl<sub>2</sub> recombine.</p><p>(0.40 - x)<sup>2</sup>/(0.80 + x) = 0.10 &rArr; x<sup>2</sup> - 0.9x + 0.08 = 0 &rArr; x = 0.10 (the other root, 0.8, is impossible).</p><p>[PCl<sub>3</sub>] = 0.40 - 0.10 = <b>0.30 mol L<sup>-1</sup></b>. It lies between the old 0.20 and the doubled 0.40.</p>'),
    P('ce-068', 4, 'equilibrium constant', 'p3', 'The value of K<sub>c</sub> at the new equilibrium is', '0.10 mol L<sup>-1</sup>, the same as before', ['0.20 mol L<sup>-1</sup>', '0.05 mol L<sup>-1</sup>', 'greater than 0.10 mol L<sup>-1</sup>, because pressure increased'], '<p>Temperature is constant, so K<sub>c</sub> does not change. Check: (0.30)(0.30)/0.90 = 0.10.</p>'),
    nat('ce-069', 4, 'K<sub>p</sub> from partial pressures', 'Pure N<sub>2</sub>O<sub>4</sub> at an initial pressure of 0.50 atm is kept in a rigid vessel. At equilibrium the total pressure is 0.75 atm. Find K<sub>p</sub> for N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> in atm.', 1.0, 0.02, 'atm', '<p>Let N<sub>2</sub>O<sub>4</sub> lose x atm: pressures 0.50 - x and 2x. Total = 0.50 + x = 0.75, so x = 0.25.</p><p>p(N<sub>2</sub>O<sub>4</sub>) = 0.25, p(NO<sub>2</sub>) = 0.50. K<sub>p</sub> = 0.25/0.25 = <b>1.0 atm</b>.</p>'),
    nat('ce-070', 4, 'mole fractions', 'One mole of N<sub>2</sub> and three moles of H<sub>2</sub> react at a total pressure of 10 atm. At equilibrium NH<sub>3</sub> is 20% by volume. Find K<sub>p</sub> in units of 10<sup>-3</sup> atm<sup>-2</sup>.', 9.26, 0.05, '10<sup>-3</sup> atm<sup>-2</sup>', '<p>If 2x mol NH<sub>3</sub> form: N<sub>2</sub> = 1 - x, H<sub>2</sub> = 3 - 3x, NH<sub>3</sub> = 2x, total 4 - 2x. 2x/(4 - 2x) = 0.2 gives x = 1/3.</p><p>Mole fractions: NH<sub>3</sub> 0.20, N<sub>2</sub> 0.20, H<sub>2</sub> 0.60. Partial pressures (&times;10): 2, 2, 6 atm.</p><p>K<sub>p</sub> = 2<sup>2</sup>/(2 &times; 6<sup>3</sup>) = 4/432 = 9.26 &times; 10<sup>-3</sup> atm<sup>-2</sup>. Answer <b>9.26</b>.</p>'),
    nat('ce-071', 4, 'van&rsquo;t Hoff equation', 'A plot of log<sub>10</sub> K against 1/T for a reaction is a straight line of slope -2610 K. Find &Delta;H in kJ mol<sup>-1</sup>. (R = 8.314)', 50, 0.5, 'kJ mol<sup>-1</sup>', '<p>log K = -&Delta;H/(2.303R) &middot; (1/T) + constant, so slope = -&Delta;H/(2.303R).</p><p>&Delta;H = 2.303 &times; 8.314 &times; 2610 = 49 970 J &asymp; <b>+50 kJ mol<sup>-1</sup></b>. A negative slope means endothermic.</p>', 'If the plot were ln K the slope would be -&Delta;H/R; using the log<sub>10</sub> slope needs the factor 2.303.'),
    nat('ce-072', 4, 'simultaneous equilibria', 'Solid NH<sub>4</sub>I dissociates: NH<sub>4</sub>I(s) &#8652; NH<sub>3</sub>(g) + HI(g), and some HI also dissociates: 2HI(g) &#8652; H<sub>2</sub>(g) + I<sub>2</sub>(g). At equilibrium p(H<sub>2</sub>) = 0.10 atm and the total pressure is 1.00 atm. Find K<sub>p</sub> for the first reaction in atm<sup>2</sup>.', 0.15, 0.005, 'atm<sup>2</sup>', '<p>H<sub>2</sub> = I<sub>2</sub> = 0.10 atm, which used 0.20 atm of HI. Let p(NH<sub>3</sub>) = y: HI = y - 0.20 (NH<sub>3</sub> = total HI formed).</p><p>Total = y + (y - 0.20) + 0.10 + 0.10 = 2y = 1.00, so y = 0.50. HI = 0.30.</p><p>K<sub>p</sub>(1) = 0.50 &times; 0.30 = <b>0.15 atm<sup>2</sup></b>. (K<sub>p</sub>(2) = 0.01/0.09 = 0.111.)</p>', 'NH<sub>3</sub> equals all the HI formed, not the HI left.'),
    mk('ce-073', 4, 'unit trap', 'A student uses concentrations in mol L<sup>-1</sup> in K<sub>c</sub> for N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> and finds K<sub>c</sub> = 4.0 L<sup>2</sup> mol<sup>-2</sup>. Which is correct about K<sub>p</sub> at 500 K? (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)', 'K<sub>p</sub> = 4.0/(41.05)<sup>2</sup> atm<sup>-2</sup> = 2.4 &times; 10<sup>-3</sup> atm<sup>-2</sup>', ['K<sub>p</sub> = 4.0 &times; (41.05)<sup>2</sup> atm<sup>-2</sup>', 'K<sub>p</sub> = 4.0 atm<sup>-2</sup>', 'K<sub>p</sub> = 4.0/41.05 atm<sup>-1</sup>'], '<p>&Delta;n<sub>g</sub> = 2 - 4 = -2, so K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-2</sup>. RT = 0.0821 &times; 500 = 41.05, so K<sub>p</sub> = 4.0/1685 = 2.4 &times; 10<sup>-3</sup> atm<sup>-2</sup>.</p>', 'A negative &Delta;n<sub>g</sub> makes K<sub>p</sub> smaller than K<sub>c</sub> numerically.'),
    mk('ce-074', 4, 'mole fractions', 'In a gas reaction, K<sub>p</sub> = K<sub>x</sub>P<sup>&Delta;n<sub>g</sub></sup>, where K<sub>x</sub> uses mole fractions. For N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, if K<sub>p</sub> is fixed, increasing the total pressure P', 'decreases K<sub>x</sub>', ['increases K<sub>x</sub>', 'leaves K<sub>x</sub> unchanged', 'increases K<sub>p</sub>'], '<p>&Delta;n<sub>g</sub> = +1, so K<sub>x</sub> = K<sub>p</sub>/P. With K<sub>p</sub> constant, a larger P lowers K<sub>x</sub>: less NO<sub>2</sub> fraction, i.e. a shift backward.</p>'),
    msq('ce-075', 4, 'K<sub>p</sub> and K<sub>c</sub>', 'For 2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g) at 300 K (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>), which statements are correct?', ['K<sub>p</sub> = K<sub>c</sub>/(RT)', 'K<sub>c</sub> has units L mol<sup>-1</sup>', 'The numerical value of K<sub>p</sub> is less than that of K<sub>c</sub>', 'K increases if the temperature is raised (the reaction is exothermic)'], [0, 1, 2], '<p>&Delta;n<sub>g</sub> = -1, so K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-1</sup>. Units of K<sub>c</sub>: (mol L<sup>-1</sup>)<sup>-1</sup>. RT = 24.6 &gt; 1, so K<sub>p</sub> &lt; K<sub>c</sub> numerically. Exothermic: K falls on heating, so D is false.</p>'),
    msq('ce-076', 4, 'degree of dissociation', 'For PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g), &Delta;H = +93 kJ mol<sup>-1</sup>. The degree of dissociation increases on', ['heating at constant volume', 'compressing the vessel', 'adding helium at constant pressure', 'adding Cl<sub>2</sub> at constant volume'], [0, 2], '<p>Heating favours the endothermic forward reaction. Helium at constant pressure expands the gas and lowers partial pressures, favouring more moles (forward). Compression and extra Cl<sub>2</sub> both push backward.</p>'),
    msq('ce-077', 4, 'unit analysis', 'For which reactions does K<sub>c</sub> have the unit L<sup>2</sup> mol<sup>-2</sup>?', ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', 'CO(g) + 2H<sub>2</sub>(g) &#8652; CH<sub>3</sub>OH(g)', '2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)', 'N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g)'], [0, 1], '<p>The unit is (mol L<sup>-1</sup>)<sup>&Delta;n</sup>, so we need &Delta;n = -2. A: 2 - 4 = -2. B: 1 - 3 = -2. C: -1. D: +1.</p>'),
    asr('ce-078', 4, 'degree of dissociation', 'The degree of dissociation of N<sub>2</sub>O<sub>4</sub> falls as the total pressure rises at constant temperature.', 'K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) is constant at a given temperature.', 0, '<p>If P rises with K<sub>p</sub> fixed, &alpha;<sup>2</sup>/(1 - &alpha;<sup>2</sup>) must fall, so &alpha; falls. R gives the relation that explains A.</p>'),
    asr('ce-079', 4, 'catalyst', 'Adding a catalyst to a system at equilibrium does not change the amounts of reactants and products present.', 'A catalyst speeds up the forward reaction but not the backward reaction.', 2, '<p>A is true: K and the composition are unchanged. R is false: a catalyst lowers the activation energy of both directions equally, so both rates rise by the same factor.</p>', 'A catalyst cannot favour one direction.'),
    stm('ce-080', 4, 'inert gas', 'Argon is added at constant volume to PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> at equilibrium. The degree of dissociation decreases.', 'Argon is added at constant volume, so the partial pressures of the reacting gases are not changed.', 2, '<p>I is wrong: nothing shifts at constant volume. II is right.</p>'),
    stm('ce-081', 4, 'inert gas', 'Argon at constant volume added to N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> shifts the equilibrium forward.', 'Argon at constant volume reduces the partial pressure of each reacting gas.', 3, '<p>Both are wrong: argon at constant volume leaves the moles per litre and the partial pressures of N<sub>2</sub>, H<sub>2</sub> and NH<sub>3</sub> unchanged; only the total pressure rises. Nothing shifts.</p>'),
    { id: 'ce-082', type: 'mcq', level: 4, format: 'statements', exams: EX[4], sub: 'equilibrium constants',
      q: '<p>Consider: (i) K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>; (ii) at equilibrium &Delta;G = 0; (iii) &Delta;G&deg; = 0 at equilibrium for every reaction; (iv) a catalyst changes the time taken to reach equilibrium. How many are correct?</p>',
      options: ['One', 'Two', 'Three', 'Four'], answer: 2,
      sol: '<p>(i) True. (ii) True: no net drive remains. (iii) False: &Delta;G&deg; = -RT ln K is zero only when K = 1; &Delta;G&deg; refers to the standard state, not to the equilibrium mixture. (iv) True: it changes the rate, not the position. Three are correct.</p>', trap: '&Delta;G and &Delta;G&deg; are different things.' },

    // ---------- Level 5 ----------
    nat('ce-083', 5, 'compression of an equilibrium', 'Pure N<sub>2</sub>O<sub>4</sub> at an initial pressure of 0.50 atm reaches equilibrium in a rigid vessel at constant T: total pressure 0.75 atm and K<sub>p</sub> = 1.0 atm. The vessel volume is now halved at constant T. Find the new total pressure in atm at equilibrium.', 1.39, 0.02, 'atm', '<p>Just after compression the partial pressures double: N<sub>2</sub>O<sub>4</sub> 0.50, NO<sub>2</sub> 1.00. Q = 1.00/0.50 = 2.0 &gt; K<sub>p</sub> = 1.0, so the reaction goes backward.</p><p>Let 2y atm of NO<sub>2</sub> turn into y atm of N<sub>2</sub>O<sub>4</sub>: (1.00 - 2y)<sup>2</sup>/(0.50 + y) = 1. This gives 4y<sup>2</sup> - 5y + 0.5 = 0, y = (5 - &radic;17)/8 = 0.1096.</p><p>Total = 1.50 - y = <b>1.39 atm</b> (less than the doubled 1.50 atm, as the shift reduces gas moles).</p>'),
    nat('ce-084', 5, 'simultaneous equilibria', 'In a closed vessel NH<sub>4</sub>I(s) &#8652; NH<sub>3</sub> + HI and 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> are both at equilibrium. The partial pressure of NH<sub>3</sub> is 0.50 atm and K<sub>p</sub> for 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> is 1/9 (about 0.111). Find the partial pressure of HI in atm.', 0.30, 0.01, 'atm', '<p>Let p(H<sub>2</sub>) = p(I<sub>2</sub>) = z. HI used = 2z, so p(HI) = 0.50 - 2z.</p><p>z<sup>2</sup>/(0.50 - 2z)<sup>2</sup> = 1/9, so z/(0.50 - 2z) = 1/3 and 3z = 0.50 - 2z, z = 0.10.</p><p>p(HI) = 0.50 - 0.20 = <b>0.30 atm</b>.</p>'),
    nat('ce-085', 5, 'mixed: chemical kinetics', 'For a reversible reaction the activation energy of the forward reaction is 100 kJ mol<sup>-1</sup> and that of the reverse reaction is 120 kJ mol<sup>-1</sup>. Find &Delta;H in kJ mol<sup>-1</sup> for the forward reaction.', -20, 0.5, 'kJ mol<sup>-1</sup>', '<p>&Delta;H = E<sub>a</sub>(forward) - E<sub>a</sub>(reverse) = 100 - 120 = <b>-20 kJ mol<sup>-1</sup></b>. The reaction is exothermic, so K falls with a rise in temperature (k<sub>b</sub> grows faster than k<sub>f</sub> because E<sub>a</sub>(reverse) is higher).</p>', 'Mixed with chemical kinetics.'),
    mk('ce-086', 5, 'degree of dissociation', 'For A(g) &#8652; 2B(g) with small degree of dissociation &alpha; (so 1 - &alpha;<sup>2</sup> &asymp; 1), if the total pressure is made four times larger at constant T, the new &alpha; is about', 'half of the old &alpha;', ['one quarter of the old &alpha;', 'twice the old &alpha;', 'unchanged'], '<p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) &asymp; 4&alpha;<sup>2</sup>P. With K<sub>p</sub> fixed, &alpha; &prop; P<sup>-1/2</sup>. P &times; 4 gives &alpha; &times; 1/2.</p>', 'Square root, not direct proportion.'),
    mk('ce-087', 5, 'van&rsquo;t Hoff graph', 'The graph of ln K (y-axis) against 1/T (x-axis) is a straight line with a <b>positive</b> slope. The reaction is', 'exothermic, and K decreases as T increases', ['endothermic, and K increases as T increases', 'exothermic, and K increases as T increases', 'endothermic, and K decreases as T increases'], '<p>ln K = -&Delta;H/(RT) + constant, so slope = -&Delta;H/R. A positive slope means &Delta;H &lt; 0 (exothermic). Rising T lowers 1/T, so ln K decreases along the positive slope.</p>', 'Reading the axis as T instead of 1/T reverses the trend.'),
    msq('ce-088', 5, 'temperature effect', 'The temperature of a mixture at equilibrium for an exothermic reaction is raised. Which are correct?', ['The rate constants of both the forward and the reverse reactions increase', 'K decreases', 'The rate of the forward reaction decreases', 'E<sub>a</sub> of the reverse reaction is greater than E<sub>a</sub> of the forward reaction'], [0, 1, 3], '<p>Both rate constants increase with T (Arrhenius), but the reverse increases by more (higher E<sub>a</sub>), so K = k<sub>f</sub>/k<sub>b</sub> decreases. The forward rate does not decrease; it increases.</p>'),
    msq('ce-089', 5, 'simultaneous equilibria', 'In a vessel, A(g) &#8652; B(g) (K<sub>1</sub>) and A(g) &#8652; C(g) (K<sub>2</sub>) both reach equilibrium. Which are correct?', ['[B]/[C] = K<sub>1</sub>/K<sub>2</sub>', '[B] + [C] + [A] is constant if A was the only starting species', 'K for B &#8652; C is K<sub>2</sub>/K<sub>1</sub>', 'The ratio [B]/[C] depends on the initial amount of A'], [0, 1, 2], '<p>[B] = K<sub>1</sub>[A] and [C] = K<sub>2</sub>[A]. So [B]/[C] = K<sub>1</sub>/K<sub>2</sub>, independent of how much A was added. For B &#8652; C, K = [C]/[B] = K<sub>2</sub>/K<sub>1</sub>. Mass (moles) conservation holds (equal moles, constant volume).</p>'),
    stm('ce-090', 5, 'inert gas', 'For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>, adding an inert gas at constant total pressure increases the degree of dissociation.', 'At constant total pressure, adding an inert gas increases the volume, which lowers the partial pressure of each reacting gas.', 0, '<p>Both are correct. Larger volume lowers partial pressures, which favours the side with more moles (dissociation), so &alpha; rises. II is the explanation.</p>'),
    ...XI,
  ],
  gens: [
    { id: 'ce-g01', type: 'nat', level: 2, exams: EX[2], sub: 'calculating K<sub>c</sub>',
      make(rng) {
        const a = pick(rng, 0.2, 1.0, 0.1); const b = pick(rng, 0.5, 2.0, 0.5); const c = pick(rng, 0.2, 1.0, 0.1);
        const K = c * c / (a * b ** 3);
        return { q: `At equilibrium, N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) has [N<sub>2</sub>] = ${a}, [H<sub>2</sub>] = ${b} and [NH<sub>3</sub>] = ${c} mol L<sup>-1</sup>. Find K<sub>c</sub> (in L<sup>2</sup> mol<sup>-2</sup>).`, answer: +K.toPrecision(4), tol: Math.abs(K) * 0.01, unit: 'L<sup>2</sup> mol<sup>-2</sup>', a, b, c,
          sol: `<p>K<sub>c</sub> = [NH<sub>3</sub>]<sup>2</sup>/([N<sub>2</sub>][H<sub>2</sub>]<sup>3</sup>) = (${c})<sup>2</sup>/(${a} &times; ${b}<sup>3</sup>) = ${(c * c).toFixed(3)}/${(a * b ** 3).toFixed(3)} = <b>${fmt(K, 3)}</b>.</p>` };
      }, verify: (p) => (p.c ** 2) / (p.a * p.b * p.b * p.b) },
    { id: 'ce-g02', type: 'nat', level: 2, exams: EX[2], sub: 'K<sub>p</sub> and K<sub>c</sub>',
      make(rng) {
        const r = choose(rng, RX.filter((x) => x[1] !== 0)); const T = pick(rng, 300, 800, 100); const Kc = pick(rng, 0.5, 8, 0.5);
        const Kp = Kc * Math.pow(RT(T), r[1]);
        return { q: `For ${r[0]}, K<sub>c</sub> = ${Kc} (units of mol and L) at ${T} K. Find K<sub>p</sub> (pressures in atm). (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, Kc, T, dn: r[1],
          sol: `<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>, with &Delta;n<sub>g</sub> = ${r[1]} and RT = 0.0821 &times; ${T} = ${RT(T).toFixed(2)}.</p><p>K<sub>p</sub> = ${Kc} &times; (${RT(T).toFixed(2)})<sup>${r[1]}</sup> = <b>${fmt(Kp, 3)}</b> (unit ${UNITP[r[1]]}).</p>` };
      }, verify: (p) => p.Kc * Math.pow(0.0821 * p.T, p.dn) },
    { id: 'ce-g03', type: 'nat', level: 3, exams: EX[3], sub: 'K<sub>p</sub> and K<sub>c</sub>',
      make(rng) {
        const r = choose(rng, RX.filter((x) => x[1] !== 0)); const T = pick(rng, 300, 800, 100); const Kp = pick(rng, 1, 10, 1) * Math.pow(10, int(rng, -2, 1));
        const Kc = Kp / Math.pow(RT(T), r[1]);
        return { q: `For ${r[0]}, K<sub>p</sub> = ${fmt(Kp, 3)} (atm units) at ${T} K. Find K<sub>c</sub> (mol and L units). (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)`, answer: +Kc.toPrecision(4), tol: Kc * 0.01, Kp, T, dn: r[1],
          sol: `<p>K<sub>c</sub> = K<sub>p</sub>(RT)<sup>-&Delta;n<sub>g</sub></sup>, &Delta;n<sub>g</sub> = ${r[1]}, RT = ${RT(T).toFixed(2)}.</p><p>K<sub>c</sub> = ${fmt(Kp, 3)} &times; (${RT(T).toFixed(2)})<sup>${-r[1]}</sup> = <b>${fmt(Kc, 3)}</b>.</p>` };
      }, verify: (p) => p.Kp / Math.pow(0.0821 * p.T, p.dn) },
    { id: 'ce-g04', type: 'nat', level: 2, exams: EX[2], sub: 'changing the equation',
      make(rng) {
        const mode = int(rng, 0, 3); const K = mode === 0 || mode === 3 ? choose(rng, [4, 9, 16, 25, 36, 64]) : choose(rng, [2, 3, 4, 5, 10]);
        const txt = ['the equation is halved (all coefficients &times; &frac12;)', 'the equation is doubled', 'the equation is reversed', 'the equation is reversed and then halved'][mode];
        const ans = [Math.sqrt(K), K * K, 1 / K, 1 / Math.sqrt(K)][mode];
        const tx = ['K<sup>1/2</sup>', 'K<sup>2</sup>', '1/K', 'K<sup>-1/2</sup>'][mode];
        return { q: `A reaction has K = ${K} at a given temperature. Find the equilibrium constant at the same temperature when ${txt}.`, answer: +ans.toPrecision(4), tol: ans * 0.005, K, mode,
          sol: `<p>The new constant is ${tx}.</p><p>= <b>${fmt(ans, 4)}</b>.</p>` };
      }, verify: (p) => [Math.sqrt(p.K), p.K ** 2, 1 / p.K, p.K ** -0.5][p.mode] },
    { id: 'ce-g05', type: 'nat', level: 3, exams: EX[3], sub: 'vapour density',
      make(rng) {
        const al = pick(rng, 0.1, 0.6, 0.05); const d = +(104.25 / (1 + al)).toFixed(2); const ans = +((104.25 - d) / d).toFixed(3);
        return { q: `The theoretical vapour density of PCl<sub>5</sub> is 104.25. At a certain temperature the equilibrium mixture of PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> has a vapour density of ${d}. Find the degree of dissociation.`, answer: ans, tol: 0.006, D: 104.25, d,
          sol: `<p>Moles increase from 1 to 1 + &alpha;, so D/d = 1 + &alpha;.</p><p>&alpha; = (104.25 - ${d})/${d} = <b>${ans}</b>.</p>` };
      }, verify: (p) => p.D / p.d - 1 },
    { id: 'ce-g06', type: 'nat', level: 3, exams: EX[3], sub: 'degree of dissociation',
      make(rng) {
        const al = pick(rng, 0.1, 0.6, 0.05); const P = choose(rng, [0.5, 1, 2, 4]); const Kp = 4 * al * al * P / (1 - al * al);
        return { q: `N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) is ${(al * 100).toFixed(0)}% dissociated at a total pressure of ${P} atm. Find K<sub>p</sub> in atm.`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, al, P,
          sol: `<p>For 1 mol: N<sub>2</sub>O<sub>4</sub> = ${(1 - al).toFixed(2)}, NO<sub>2</sub> = ${(2 * al).toFixed(2)}, total = ${(1 + al).toFixed(2)}.</p><p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 4(${al})<sup>2</sup>(${P})/(1 - ${(al * al).toFixed(4)}) = <b>${fmt(Kp, 3)} atm</b>.</p>` };
      }, verify: (p) => { const t = 1 + p.al; return ((2 * p.al * p.P / t) ** 2) / ((1 - p.al) * p.P / t); } },
    { id: 'ce-g07', type: 'nat', level: 3, exams: EX[3], sub: 'degree of dissociation',
      make(rng) {
        const al = pick(rng, 0.1, 0.8, 0.05); const P = choose(rng, [0.5, 1, 2, 5]); const Kp = al * al * P / (1 - al * al);
        return { q: `PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is ${(al * 100).toFixed(0)}% dissociated at a total pressure of ${P} atm. Find K<sub>p</sub> in atm.`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, al, P,
          sol: `<p>For 1 mol: PCl<sub>5</sub> = ${(1 - al).toFixed(2)}; PCl<sub>3</sub> = Cl<sub>2</sub> = ${al}; total = ${(1 + al).toFixed(2)}.</p><p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = (${al})<sup>2</sup>(${P})/(1 - ${(al * al).toFixed(4)}) = <b>${fmt(Kp, 3)} atm</b>.</p>` };
      }, verify: (p) => { const t = 1 + p.al; return ((p.al * p.P / t) ** 2) / ((1 - p.al) * p.P / t); } },
    { id: 'ce-g08', type: 'nat', level: 3, exams: EX[3], sub: 'ICE table',
      make(rng) {
        const k = choose(rng, [2, 3, 4, 6, 8]); const Kc = k * k; const hi = 2 * k / (2 + k);
        return { q: `One mole each of H<sub>2</sub> and I<sub>2</sub> are placed in a 1 L vessel. K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI is ${Kc} at that temperature. Find the moles of HI at equilibrium.`, answer: +hi.toFixed(3), tol: 0.01, unit: 'mol', k, Kc,
          sol: `<p>Let x mol of each react: [HI] = 2x, [H<sub>2</sub>] = [I<sub>2</sub>] = 1 - x. K<sub>c</sub> = (2x)<sup>2</sup>/(1 - x)<sup>2</sup> = ${Kc}.</p><p>Taking square roots: 2x/(1 - x) = ${k}, so x = ${k}/${2 + k} and HI = 2x = <b>${hi.toFixed(3)} mol</b>.</p>` };
      }, verify: (p) => { const x = (p.k) / (2 + p.k); return 2 * x; } },
    { id: 'ce-g09', type: 'nat', level: 3, exams: EX[3], sub: 'van&rsquo;t Hoff equation',
      make(rng) {
        const dH = pick(rng, 20, 100, 10); const T1 = choose(rng, [300, 350, 400]); const T2 = T1 + choose(rng, [10, 20, 25, 50]);
        const ans = Math.exp((dH * 1000 / 8.314) * (1 / T1 - 1 / T2));
        return { q: `A reaction has &Delta;H = +${dH} kJ mol<sup>-1</sup>. By what factor (K<sub>2</sub>/K<sub>1</sub>) does K change when the temperature goes from ${T1} K to ${T2} K? (R = 8.314; &Delta;H constant)`, answer: +ans.toPrecision(4), tol: ans * 0.01, dH, T1, T2,
          sol: `<p>ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (${dH * 1000}/8.314)(1/${T1} - 1/${T2}) = ${Math.log(ans).toFixed(3)}.</p><p>K<sub>2</sub>/K<sub>1</sub> = <b>${fmt(ans, 3)}</b>.</p>` };
      }, verify: (p) => Math.pow(10, (p.dH * 1000 / (2.303 * 8.314)) * (1 / p.T1 - 1 / p.T2)) },
    { id: 'ce-g10', type: 'nat', level: 4, exams: EX[4], sub: 'van&rsquo;t Hoff equation',
      make(rng) {
        const dH = pick(rng, 30, 90, 10) * (rng() < 0.5 ? -1 : 1); const T1 = 300; const T2 = choose(rng, [350, 400, 500]); const K1 = choose(rng, [1, 10, 100]);
        const K2 = +(K1 * Math.exp((dH * 1000 / 8.314) * (1 / T1 - 1 / T2))).toPrecision(4);
        const ans = 8.314 * Math.log(K2 / K1) / (1 / T1 - 1 / T2) / 1000;
        return { q: `For a reaction, K = ${K1} at ${T1} K and K = ${K2} at ${T2} K. Find &Delta;H in kJ mol<sup>-1</sup>, assuming it is constant. (R = 8.314)`, answer: +ans.toFixed(2), tol: 0.5, K1, K2, T1, T2,
          sol: `<p>&Delta;H = R ln(K<sub>2</sub>/K<sub>1</sub>)/(1/T<sub>1</sub> - 1/T<sub>2</sub>) = 8.314 &times; ln(${K2}/${K1}) / (1/${T1} - 1/${T2}).</p><p>= 8.314 &times; ${Math.log(K2 / K1).toFixed(3)} / ${(1 / T1 - 1 / T2).toExponential(3)} = <b>${ans.toFixed(1)} kJ mol<sup>-1</sup></b>${ans > 0 ? ' (K rises with T: endothermic)' : ' (K falls with T: exothermic)'}.</p>` };
      }, verify: (p) => (Math.log(p.K2 / p.K1) * 8.314 * p.T1 * p.T2) / (p.T2 - p.T1) / 1000 },
    { id: 'ce-g11', type: 'mcq', level: 2, exams: EX[2], sub: 'reaction quotient',
      make(rng) {
        const r = choose(rng, [2, 3, 4]); const a = choose(rng, [0.1, 0.2, 0.5]); const mode = int(rng, 0, 2);
        const c = [(r - 1) * a, r * a, (r + 1) * a][mode]; const K = r * r; const Q = (c * c) / (a * a);
        const right = ['The reaction goes forward', 'The reaction is at equilibrium', 'The reaction goes backward'][mode];
        const { options, answer } = shuffleOpts(rng, right, ['The reaction goes forward', 'The reaction is at equilibrium', 'The reaction goes backward', 'Cannot be decided without a catalyst'].filter((x) => x !== right));
        return { q: `For A(g) + B(g) &#8652; C(g) + D(g), K<sub>c</sub> = ${K}. A mixture has [A] = [B] = ${a} and [C] = [D] = ${+c.toFixed(3)} mol L<sup>-1</sup>. Which statement is correct?`, options, answer, a, c, K, right,
          sol: `<p>Q<sub>c</sub> = [C][D]/([A][B]) = (${+c.toFixed(3)})<sup>2</sup>/(${a})<sup>2</sup> = ${+Q.toFixed(2)}.</p><p>Compare with K<sub>c</sub> = ${K}: ${Q < K - 1e-9 ? 'Q &lt; K, so products form (forward)' : Q > K + 1e-9 ? 'Q &gt; K, so products are used up (backward)' : 'Q = K, so equilibrium'}. <b>${right}</b>.</p>` };
      }, verify: (p) => p.options.indexOf(p.right) },
    { id: 'ce-g12', type: 'nat', level: 3, exams: EX[3], sub: 'mixed: thermodynamics',
      make(rng) {
        const m = int(rng, -3, 6); const T = choose(rng, [298, 300, 310, 350]); const dG = -m * 2.303 * 8.314 * T / 1000;
        return { q: `At ${T} K the equilibrium constant of a reaction is 10<sup>${m}</sup>. Find &Delta;G&deg; in kJ mol<sup>-1</sup>. (R = 8.314)`, answer: +dG.toFixed(2), tol: 0.1, unit: 'kJ mol<sup>-1</sup>', m, T,
          sol: `<p>&Delta;G&deg; = -2.303RT log K = -2.303 &times; 8.314 &times; ${T} &times; (${m}) = <b>${dG.toFixed(2)} kJ mol<sup>-1</sup></b>.</p>${m < 0 ? '<p>K &lt; 1, so &Delta;G&deg; is positive.</p>' : ''}` };
      }, verify: (p) => (-p.m * Math.LN10 * 8.314 * p.T) / 1000 },
    { id: 'ce-g13', type: 'nat', level: 3, exams: EX[3], sub: 'degree of dissociation',
      make(rng) {
        const al = pick(rng, 0.1, 0.8, 0.1); const P0 = pick(rng, 0.5, 4, 0.5); const Pt = P0 * (1 + al);
        return { q: `Pure A(g) at ${P0} atm is placed in a rigid vessel and dissociates as A(g) &#8652; B(g) + C(g). At equilibrium the total pressure is ${+Pt.toFixed(3)} atm at the same temperature. Find the degree of dissociation.`, answer: al, tol: 0.01, P0, Pt: +Pt.toFixed(3),
          sol: `<p>For A &#8652; B + C at constant volume, pressure is proportional to moles. Moles go from 1 to 1 + &alpha;.</p><p>P<sub>total</sub> = P<sub>0</sub>(1 + &alpha;), so &alpha; = ${+Pt.toFixed(3)}/${P0} - 1 = <b>${al}</b>.</p>` };
      }, verify: (p) => p.Pt / p.P0 - 1 },
    { id: 'ce-g14', type: 'nat', level: 2, exams: EX[2], sub: 'heterogeneous equilibrium',
      make(rng) {
        const kind = int(rng, 0, 1); const P = pick(rng, 0.2, 2, 0.1);
        const Kp = kind === 0 ? (P / 2) ** 2 : 4 * P ** 3 / 27;
        return { q: kind === 0 ? `NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g). At equilibrium the total pressure in the vessel is ${P} atm. Find K<sub>p</sub> in atm<sup>2</sup>.` : `NH<sub>2</sub>COONH<sub>4</sub>(s) &#8652; 2NH<sub>3</sub>(g) + CO<sub>2</sub>(g). At equilibrium the total pressure is ${P} atm. Find K<sub>p</sub> in atm<sup>3</sup>.`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, kind, P,
          sol: kind === 0 ? `<p>The two gases are in equal amounts, so each has p = ${P}/2 = ${P / 2} atm. K<sub>p</sub> = (${P / 2})<sup>2</sup> = <b>${fmt(Kp, 3)} atm<sup>2</sup></b>.</p>` : `<p>The gases are in the ratio 2 : 1, so p(NH<sub>3</sub>) = 2P/3 = ${fmt(2 * P / 3, 3)} and p(CO<sub>2</sub>) = P/3 = ${fmt(P / 3, 3)} atm.</p><p>K<sub>p</sub> = (2P/3)<sup>2</sup>(P/3) = 4P<sup>3</sup>/27 = <b>${fmt(Kp, 3)} atm<sup>3</sup></b>.</p>` };
      }, verify: (p) => (p.kind === 0 ? (p.P / 2) ** 2 : ((2 * p.P) / 3) ** 2 * (p.P / 3)) },
    { id: 'ce-g15', type: 'mcq', level: 1, exams: EX[1], sub: 'units of K',
      make(rng) {
        const r = choose(rng, RX); const dn = r[1]; const right = UNIT[dn];
        const all = Object.values(UNIT);
        const { options, answer } = shuffleOpts(rng, right, all.filter((x) => x !== right).slice(0, 3));
        return { q: `The unit of K<sub>c</sub> (concentrations in mol L<sup>-1</sup>) for ${r[0]} is`, options, answer, dn, right,
          sol: `<p>&Delta;n = (moles of gaseous products) - (moles of gaseous reactants) = ${dn}. The unit is (mol L<sup>-1</sup>)<sup>${dn}</sup> = <b>${right}</b>.</p>` };
      }, verify: (p) => p.options.indexOf(UNIT[p.dn]) },
    { id: 'ce-g16', type: 'nat', level: 4, exams: EX[4], sub: 'ICE table',
      make(rng) {
        const c0 = choose(rng, [1, 2]); const x2 = +(pick(rng, 0.2, 0.8, 0.1) * c0).toFixed(2);
        const Kc = +(x2 * x2 / (c0 - x2)).toFixed(4);
        return { q: `A(g) &#8652; B(g) + C(g) has K<sub>c</sub> = ${Kc} mol L<sup>-1</sup>. The vessel starts with ${c0} mol L<sup>-1</sup> of A only. Find [B] at equilibrium in mol L<sup>-1</sup>.`, answer: x2, tol: 0.01, unit: 'mol L<sup>-1</sup>', c0, Kc, x2,
          sol: `<p>Let [B] = [C] = x and [A] = ${c0} - x. Then x<sup>2</sup>/(${c0} - x) = ${Kc}, i.e. x<sup>2</sup> + ${Kc}x - ${+(Kc * c0).toFixed(4)} = 0.</p><p>x = [-${Kc} + &radic;(${Kc}<sup>2</sup> + 4 &times; ${+(Kc * c0).toFixed(4)})]/2 = <b>${x2}</b>.</p>` };
      }, verify: (p) => { const b = p.Kc, c = -p.Kc * p.c0; return (-b + Math.sqrt(b * b - 4 * c)) / 2; } },
    ...XGN,
  ],
};
// Sign display tidied ("+ -3" reads "- 3", "1x" reads "x"): signs() in ../_util.js.
export default tidyGens({ ...V5BASE, groups: { ...V5BASE.groups, ...V5GR }, items: [...V5BASE.items, ...V5I], gens: [...V5BASE.gens, ...V5G] }, ['ce-g16', 'ce-v5g1']);
